  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 2} [3x^2 - 5x + 7]$$\text{.}$', '["$10$", "$-9$", "$7$", "$9$"]'::jsonb, 3, '$\text{Since}$ $f(x) = 3 x^{2} - 5 x + 7$ $\text{is}$ $\text{continuous}$ $\text{at}$ $x=2$ $\text{(the}$ $\text{denominator,}$ $\text{if}$ $\text{any,}$ $\text{is}$ $\text{not}$ $\text{zero}$ $\text{there),}$ $\text{substitute}$ $\text{directly:}$ $\lim_{x \to 2} 3 x^{2} - 5 x + 7$ $=$ $3 \cdot 2^{2} - 5 \cdot 2 + 7$ $=$ $9$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
