  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 3} [(x^2 - 9)/(x - 3)]$$\text{.}$', '["$0$", "$8$", "$6$", "$\\text{does}$ $\\text{not}$ $\\text{exist}$ $\\text{(}$$\\infty$$\\text{)}$"]'::jsonb, 2, '$\text{Direct}$ $\text{substitution}$ $\text{gives}$ $\frac{0}{0}$$\text{,}$ $\text{a}$ $0/0$ $\text{form.}$ $\text{Factor:}$ $\dfrac{x^{2} - 9}{x - 3}$ $=$ $\dfrac{\left(x - 3\right) \left(x + 3\right)}{x - 3}$$\text{,}$ $\text{and}$ $\text{cancel}$ $\text{the}$ $\text{common}$ $\text{factor}$ $\text{to}$ $\text{get}$ $x + 3$ $\text{(valid}$ $\text{for}$ $x \neq 3$$\text{).}$ $\text{Substituting}$ $x=3$$\text{:}$ $3 + 3 = 6$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 2} [(x^2 - 4)/(x - 2)]$$\text{.}$', '["$4$", "$6$", "$0$", "$\\text{does}$ $\\text{not}$ $\\text{exist}$ $\\text{(}$$\\infty$$\\text{)}$"]'::jsonb, 0, '$\text{Direct}$ $\text{substitution}$ $\text{gives}$ $\frac{0}{0}$$\text{,}$ $\text{a}$ $0/0$ $\text{form.}$ $\text{Factor:}$ $\dfrac{x^{2} - 4}{x - 2}$ $=$ $\dfrac{\left(x - 2\right) \left(x + 2\right)}{x - 2}$$\text{,}$ $\text{and}$ $\text{cancel}$ $\text{the}$ $\text{common}$ $\text{factor}$ $\text{to}$ $\text{get}$ $x + 2$ $\text{(valid}$ $\text{for}$ $x \neq 2$$\text{).}$ $\text{Substituting}$ $x=2$$\text{:}$ $2 + 2 = 4$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 2} [(x^2 - 5x + 6)/(x - 2)]$$\text{.}$', '["$\\text{does}$ $\\text{not}$ $\\text{exist}$ $\\text{(}$$\\infty$$\\text{)}$", "$-1$", "$0$", "$1$"]'::jsonb, 1, '$\text{Direct}$ $\text{substitution}$ $\text{gives}$ $\frac{0}{0}$$\text{,}$ $\text{a}$ $0/0$ $\text{form.}$ $\text{Factor:}$ $\dfrac{x^{2} - 5 x + 6}{x - 2}$ $=$ $\dfrac{\left(x - 3\right) \left(x - 2\right)}{x - 2}$$\text{,}$ $\text{and}$ $\text{cancel}$ $\text{the}$ $\text{common}$ $\text{factor}$ $\text{to}$ $\text{get}$ $x - 3$ $\text{(valid}$ $\text{for}$ $x \neq 2$$\text{).}$ $\text{Substituting}$ $x=2$$\text{:}$ $2 - 3 = -1$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
