  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{0}^{2} x^2 \, dx$$\text{.}$', '["$5/3$", "$-8/3$", "$8/3$", "$11/3$"]'::jsonb, 2, '$\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \frac{x^{3}}{3}$$\text{.}$ $\text{By}$ $\text{the}$ $\text{Fundamental}$ $\text{Theorem,}$ $\int_{0}^{2} x^{2} \, dx$ $=$ $F(2) - F(0)$ $=$ $(\frac{2^{3}}{3} = \frac{8}{3})$ $-$ $(\frac{0^{3}}{3} = 0)$ $=$ $\frac{8}{3} - 0$ $=$ $\frac{8}{3}$$\text{.}$', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{1}^{4} 3x - 1 \, dx$$\text{.}$', '["$41/2$", "$-39/2$", "$20$", "$39/2$"]'::jsonb, 3, '$\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \frac{3 x^{2}}{2} - x$$\text{.}$ $\text{By}$ $\text{the}$ $\text{Fundamental}$ $\text{Theorem,}$ $\int_{1}^{4} 3 x - 1 \, dx$ $=$ $F(4) - F(1)$ $=$ $(\frac{4 \left(-2 + 3 \cdot 4\right)}{2}$ $=$ $20)$ $-$ $(\frac{1 \left(-2 + 3 \cdot 1\right)}{2}$ $=$ $\frac{1}{2})$ $=$ $20 - \frac{1}{2}$ $=$ $\frac{39}{2}$$\text{.}$', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{0}^{3} x^2 - 4x + 3 \, dx$$\text{.}$', '["$-1$", "$2$", "$0$", "$1$"]'::jsonb, 2, '$\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \frac{x^{3}}{3} - 2 x^{2} + 3 x$$\text{.}$ $\text{By}$ $\text{the}$ $\text{Fundamental}$ $\text{Theorem,}$ $\int_{0}^{3} x^{2} - 4 x + 3 \, dx$ $=$ $F(3) - F(0)$ $=$ $(\frac{3 \left(9 - 6 \cdot 3 + 3^{2}\right)}{3}$ $=$ $0)$ $-$ $(\frac{0 \left(9 - 6 \cdot 0 + 0^{2}\right)}{3}$ $=$ $0)$ $=$ $0 - 0$ $=$ $0$$\text{.}$', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{-1}^{2} 2x + 1 \, dx$$\text{.}$', '["$7$", "$5$", "$6$", "$-6$"]'::jsonb, 2, '$\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = x^{2} + x$$\text{.}$ $\text{By}$ $\text{the}$ $\text{Fundamental}$ $\text{Theorem,}$ $\int_{-1}^{2} 2 x + 1 \, dx$ $=$ $F(2) - F(-1)$ $=$ $(2^{2} + 2 = 6)$ $-$ $(\left(-1\right)^{2} + -1 = 0)$ $=$ $6 - 0$ $=$ $6$$\text{.}$', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{0}^{1} x^3 \, dx$$\text{.}$', '["$-3/4$", "$1/4$", "$-1/4$", "$5/4$"]'::jsonb, 1, '$\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \frac{x^{4}}{4}$$\text{.}$ $\text{By}$ $\text{the}$ $\text{Fundamental}$ $\text{Theorem,}$ $\int_{0}^{1} x^{3} \, dx$ $=$ $F(1) - F(0)$ $=$ $(\frac{1^{4}}{4} = \frac{1}{4})$ $-$ $(\frac{0^{4}}{4} = 0)$ $=$ $\frac{1}{4} - 0$ $=$ $\frac{1}{4}$$\text{.}$', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{-1}^{1} 4 - x^2 \, dx$$\text{.}$', '["$-22/3$", "$22/3$", "$25/3$", "$11/3$"]'::jsonb, 1, '$\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = - \frac{x^{3}}{3} + 4 x$$\text{.}$ $\text{By}$ $\text{the}$ $\text{Fundamental}$ $\text{Theorem,}$ $\int_{-1}^{1} 4 - x^{2} \, dx$ $=$ $F(1) - F(-1)$ $=$ $(\frac{1 \left(12 - 1^{2}\right)}{3}$ $=$ $\frac{11}{3})$ $-$ $(\frac{\left(-1\right) \left(12 - \left(-1\right)^{2}\right)}{3}$ $=$ $- \frac{11}{3})$ $=$ $\frac{11}{3} - - \frac{11}{3}$ $=$ $\frac{22}{3}$$\text{.}$', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{area}$ $\text{of}$ $\text{the}$ $\text{region}$ $\text{bounded}$ $\text{by}$ $y = x^2$$\text{,}$ $\text{the}$ $\text{x-axis,}$ $x=0$$\text{,}$ $\text{and}$ $\text{x=2.}$', '["$16/3$", "$11/3$", "$-8/3$", "$8/3$"]'::jsonb, 3, '$y=x^{2}$ $\text{does}$ $\text{not}$ $\text{cross}$ $\text{the}$ $x$$\text{-axis}$ $\text{between}$ $x=0$ $\text{and}$ $x=2$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $\int_{0}^{2} x^{2} \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \frac{x^{3}}{3}$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $F(2) - F(0)$ $=$ $\frac{2^{3}}{3} - (\frac{0^{3}}{3})$ $=$ $\frac{8}{3}$$\text{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{area}$ $\text{of}$ $\text{the}$ $\text{region}$ $\text{bounded}$ $\text{by}$ $y = 3x$$\text{,}$ $\text{the}$ $\text{x-axis,}$ $x=0$$\text{,}$ $\text{and}$ $\text{x=4.}$', '["$-24$", "$25$", "$48$", "$24$"]'::jsonb, 3, '$y=3 x$ $\text{does}$ $\text{not}$ $\text{cross}$ $\text{the}$ $x$$\text{-axis}$ $\text{between}$ $x=0$ $\text{and}$ $x=4$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $\int_{0}^{4} 3 x \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \frac{3 x^{2}}{2}$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $F(4) - F(0)$ $=$ $\frac{3 \cdot 4^{2}}{2}$ $-$ $(\frac{3 \cdot 0^{2}}{2})$ $=$ $24$$\text{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{area}$ $\text{of}$ $\text{the}$ $\text{region}$ $\text{bounded}$ $\text{by}$ $y = 4 - x^2$$\text{,}$ $\text{the}$ $\text{x-axis,}$ $x=-2$$\text{,}$ $\text{and}$ $\text{x=2.}$', '["$32/3$", "$-32/3$", "$35/3$", "$64/3$"]'::jsonb, 0, '$y=4 - x^{2}$ $\text{does}$ $\text{not}$ $\text{cross}$ $\text{the}$ $x$$\text{-axis}$ $\text{between}$ $x=-2$ $\text{and}$ $x=2$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $\int_{-2}^{2} 4 - x^{2} \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = - \frac{x^{3}}{3} + 4 x$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $F(2) - F(-2)$ $=$ $\frac{2 \left(12 - 2^{2}\right)}{3}$ $-$ $(\frac{\left(-2\right) \left(12 - \left(-2\right)^{2}\right)}{3})$ $=$ $\frac{32}{3}$$\text{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{area}$ $\text{of}$ $\text{the}$ $\text{region}$ $\text{bounded}$ $\text{by}$ $y = x^3$$\text{,}$ $\text{the}$ $\text{x-axis,}$ $x=0$$\text{,}$ $\text{and}$ $\text{x=2.}$', '["$8$", "$-4$", "$4$", "$5$"]'::jsonb, 2, '$y=x^{3}$ $\text{does}$ $\text{not}$ $\text{cross}$ $\text{the}$ $x$$\text{-axis}$ $\text{between}$ $x=0$ $\text{and}$ $x=2$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $\int_{0}^{2} x^{3} \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \frac{x^{4}}{4}$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $F(2) - F(0)$ $=$ $\frac{2^{4}}{4} - (\frac{0^{4}}{4})$ $=$ $4$$\text{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{area}$ $\text{of}$ $\text{the}$ $\text{region}$ $\text{bounded}$ $\text{by}$ $y$ $=$ $x + 3 and y$ $=$ $x^2 - 1 between x$ $=$ $-1 and x$ $=$ $1$$\text{.}$', '["$6$", "$-22/3$", "$22/3$", "$28/3$"]'::jsonb, 2, '$\text{Between}$ $x=-1$ $\text{and}$ $x=1$$\text{,}$ $y=x + 3$ $\text{lies}$ $\text{above}$ $y=x^{2} - 1$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $\int_{-1}^{1} [(x + 3) - (x^{2} - 1)] \, dx$ $=$ $\int_{-1}^{1} - x^{2} + x + 4 \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x)$ $=$ $- \frac{x^{3}}{3}$ $+$ $\frac{x^{2}}{2}$ $+$ $4 x$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $F(1) - F(-1)$ $=$ $\frac{1 \left(24 + 3 \cdot 1 - 2 \cdot 1^{2}\right)}{6}$ $-$ $(\frac{\left(-1\right) \left(24 + 3 \left(-1\right) - 2 \left(-1\right)^{2}\right)}{6})$ $=$ $\frac{22}{3}$$\text{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{area}$ $\text{of}$ $\text{the}$ $\text{region}$ $\text{bounded}$ $\text{by}$ $y$ $=$ $6 - x and y$ $=$ $x^2 between x$ $=$ $-3 and x$ $=$ $2$$\text{.}$', '["$65/2$", "$-125/6$", "$137/6$", "$125/6$"]'::jsonb, 3, '$\text{Between}$ $x=-3$ $\text{and}$ $x=2$$\text{,}$ $y=6 - x$ $\text{lies}$ $\text{above}$ $y=x^{2}$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $\int_{-3}^{2} [(6 - x) - (x^{2})] \, dx$ $=$ $\int_{-3}^{2} - x^{2} - x + 6 \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x)$ $=$ $- \frac{x^{3}}{3}$ $-$ $\frac{x^{2}}{2}$ $+$ $6 x$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $F(2) - F(-3)$ $=$ $\frac{2 \left(36 - 3 \cdot 2 - 2 \cdot 2^{2}\right)}{6}$ $-$ $(\frac{\left(-3\right) \left(36 - 3 \left(-3\right) - 2 \left(-3\right)^{2}\right)}{6})$ $=$ $\frac{125}{6}$$\text{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{area}$ $\text{of}$ $\text{the}$ $\text{region}$ $\text{bounded}$ $\text{by}$ $y$ $=$ $x + 5 and y$ $=$ $x^2 - 1 between x$ $=$ $-2 and x$ $=$ $3$$\text{.}$', '["$137/6$", "$55/2$", "$-125/6$", "$125/6$"]'::jsonb, 3, '$\text{Between}$ $x=-2$ $\text{and}$ $x=3$$\text{,}$ $y=x + 5$ $\text{lies}$ $\text{above}$ $y=x^{2} - 1$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $\int_{-2}^{3} [(x + 5) - (x^{2} - 1)] \, dx$ $=$ $\int_{-2}^{3} - x^{2} + x + 6 \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x)$ $=$ $- \frac{x^{3}}{3}$ $+$ $\frac{x^{2}}{2}$ $+$ $6 x$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $F(3) - F(-2)$ $=$ $\frac{3 \left(36 + 3 \cdot 3 - 2 \cdot 3^{2}\right)}{6}$ $-$ $(\frac{\left(-2\right) \left(36 + 3 \left(-2\right) - 2 \left(-2\right)^{2}\right)}{6})$ $=$ $\frac{125}{6}$$\text{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{disc}$ $\text{method,}$ $\text{find}$ $\text{the}$ $\text{volume}$ $\text{of}$ $\text{the}$ $\text{solid}$ $\text{formed}$ $\text{by}$ $\text{revolving}$ $y = x$ $\text{about}$ $\text{the}$ $\text{x-axis}$ $\text{from}$ $\text{x=0}$ $\text{to}$ $\text{x=4.}$', '["$128\\pi/3$", "$-64\\pi/3$", "$8\\pi$", "$64\\pi/3$"]'::jsonb, 3, '$V$ $=$ $\pi \int_{0}^{4} [x]^2 \, dx$ $=$ $\pi \int_{0}^{4} x^{2} \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{of}$ $\text{the}$ $\text{integrand}$ $\text{is}$ $F(x) = \frac{x^{3}}{3}$$\text{,}$ $\text{so}$ $V$ $=$ $\pi \left[F(4) - F(0)\right]$ $=$ $\pi \left[\frac{4^{3}}{3} - \left(\frac{0^{3}}{3}\right)\right]$ $=$ $\frac{64 \pi}{3}$$\text{.}$', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{disc}$ $\text{method,}$ $\text{find}$ $\text{the}$ $\text{volume}$ $\text{of}$ $\text{the}$ $\text{solid}$ $\text{formed}$ $\text{by}$ $\text{revolving}$ $y = \sqrt{x}$ $\text{about}$ $\text{the}$ $\text{x-axis}$ $\text{from}$ $\text{x=0}$ $\text{to}$ $\text{x=4.}$', '["$16\\pi$", "$8\\pi$", "$16\\pi/3$", "$-8\\pi$"]'::jsonb, 1, '$V$ $=$ $\pi \int_{0}^{4} [\sqrt{x}]^2 \, dx$ $=$ $\pi \int_{0}^{4} x \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{of}$ $\text{the}$ $\text{integrand}$ $\text{is}$ $F(x) = \frac{x^{2}}{2}$$\text{,}$ $\text{so}$ $V$ $=$ $\pi \left[F(4) - F(0)\right]$ $=$ $\pi \left[\frac{4^{2}}{2} - \left(\frac{0^{2}}{2}\right)\right]$ $=$ $8 \pi$$\text{.}$', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{disc}$ $\text{method,}$ $\text{find}$ $\text{the}$ $\text{volume}$ $\text{of}$ $\text{the}$ $\text{solid}$ $\text{formed}$ $\text{by}$ $\text{revolving}$ $y = 2$ $\text{about}$ $\text{the}$ $\text{x-axis}$ $\text{from}$ $\text{x=0}$ $\text{to}$ $\text{x=3.}$', '["$12\\pi$", "$24\\pi$", "$-12\\pi$", "$6\\pi$"]'::jsonb, 0, '$V$ $=$ $\pi \int_{0}^{3} [2]^2 \, dx$ $=$ $\pi \int_{0}^{3} 4 \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{of}$ $\text{the}$ $\text{integrand}$ $\text{is}$ $F(x) = 4 x$$\text{,}$ $\text{so}$ $V$ $=$ $\pi \left[F(3) - F(0)\right]$ $=$ $\pi \left[4 \cdot 3 - \left(4 \cdot 0\right)\right]$ $=$ $12 \pi$$\text{.}$', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{disc}$ $\text{method,}$ $\text{find}$ $\text{the}$ $\text{volume}$ $\text{of}$ $\text{the}$ $\text{solid}$ $\text{formed}$ $\text{by}$ $\text{revolving}$ $y = x^2$ $\text{about}$ $\text{the}$ $\text{x-axis}$ $\text{from}$ $\text{x=0}$ $\text{to}$ $\text{x=1.}$', '["$\\pi/3$", "$-\\pi/5$", "$2\\pi/5$", "$\\pi/5$"]'::jsonb, 3, '$V$ $=$ $\pi \int_{0}^{1} [x^{2}]^2 \, dx$ $=$ $\pi \int_{0}^{1} x^{4} \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{of}$ $\text{the}$ $\text{integrand}$ $\text{is}$ $F(x) = \frac{x^{5}}{5}$$\text{,}$ $\text{so}$ $V$ $=$ $\pi \left[F(1) - F(0)\right]$ $=$ $\pi \left[\frac{1^{5}}{5} - \left(\frac{0^{5}}{5}\right)\right]$ $=$ $\frac{\pi}{5}$$\text{.}$', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \ln(3x^2 + 5)$$\text{.}$', '["$-6x/(3x^2 + 5)$", "$1/(3x^2 + 5)$", "$6x/(3x^2 + 5)$", "$6x$"]'::jsonb, 2, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$$\text{.}$ $\text{With}$ $u = 3 x^{2} + 5$$\text{,}$ $u'' = 6 x$$\text{,}$ $\text{giving}$ $f''(x)$ $=$ $\dfrac{6 x}{3 x^{2} + 5}$ $=$ $\frac{6 x}{3 x^{2} + 5}$$\text{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \ln(\cos(x))$$\text{.}$', '["$1/\\cos(x)$", "$-\\sin(x)$", "$\\tan(x)$", "$-\\tan(x)$"]'::jsonb, 3, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$$\text{.}$ $\text{With}$ $u = \cos{\left(x \right)}$$\text{,}$ $u'' = - \sin{\left(x \right)}$$\text{,}$ $\text{giving}$ $f''(x)$ $=$ $\dfrac{- \sin{\left(x \right)}}{\cos{\left(x \right)}}$ $=$ $- \tan{\left(x \right)}$$\text{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \ln(x^3 - 2)$$\text{.}$', '["$1/(x^3 - 2)$", "$3x^2/(x^3 - 2)$", "$-3x^2/(x^3 - 2)$", "$3x^2$"]'::jsonb, 1, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$$\text{.}$ $\text{With}$ $u = x^{3} - 2$$\text{,}$ $u'' = 3 x^{2}$$\text{,}$ $\text{giving}$ $f''(x)$ $=$ $\dfrac{3 x^{2}}{x^{3} - 2}$ $=$ $\frac{3 x^{2}}{x^{3} - 2}$$\text{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \ln(5x - 1)$$\text{.}$', '["$-5/(5x - 1)$", "$5$", "$5/(5x - 1)$", "$1/(5x - 1)$"]'::jsonb, 2, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$$\text{.}$ $\text{With}$ $u = 5 x - 1$$\text{,}$ $u'' = 5$$\text{,}$ $\text{giving}$ $f''(x)$ $=$ $\dfrac{5}{5 x - 1}$ $=$ $\frac{5}{5 x - 1}$$\text{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = e^{4x}$$\text{.}$', '["$-4e^{4x}$", "$4e^{4x}$", "$e^{4x}$", "$4$"]'::jsonb, 1, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[e^u] = e^u \cdot u''$$\text{.}$ $\text{With}$ $u = 4 x$$\text{,}$ $u'' = 4$$\text{,}$ $\text{giving}$ $f''(x) = e^{4 x} \cdot 4 = 4 e^{4 x}$$\text{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = e^{x^2}$$\text{.}$', '["$\\text{-2xe\\textasciicircum{}(x\\textasciicircum{}2)}$", "$2x$", "$\\text{2xe\\textasciicircum{}(x\\textasciicircum{}2)}$", "$e^{x^2}$"]'::jsonb, 2, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[e^u] = e^u \cdot u''$$\text{.}$ $\text{With}$ $u = x^{2}$$\text{,}$ $u'' = 2 x$$\text{,}$ $\text{giving}$ $f''(x)$ $=$ $e^{x^{2}} \cdot 2 x$ $=$ $2 x e^{x^{2}}$$\text{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = e^{\sin(x)}$$\text{.}$', '["$e^{\\sin(x)}$", "$\\cos(x)$", "$-e^{\\sin(x)}\\cos(x)$", "$e^{\\sin(x)}\\cos(x)$"]'::jsonb, 3, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[e^u] = e^u \cdot u''$$\text{.}$ $\text{With}$ $u = \sin{\left(x \right)}$$\text{,}$ $u'' = \cos{\left(x \right)}$$\text{,}$ $\text{giving}$ $f''(x)$ $=$ $e^{\sin{\left(x \right)}} \cdot \cos{\left(x \right)}$ $=$ $e^{\sin{\left(x \right)}} \cos{\left(x \right)}$$\text{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = e^{2x - 1}$$\text{.}$', '["$2$", "$2e^{2x - 1}$", "$-2e^{2x - 1}$", "$e^{2x - 1}$"]'::jsonb, 1, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[e^u] = e^u \cdot u''$$\text{.}$ $\text{With}$ $u = 2 x - 1$$\text{,}$ $u'' = 2$$\text{,}$ $\text{giving}$ $f''(x)$ $=$ $e^{2 x - 1} \cdot 2$ $=$ $2 e^{2 x - 1}$$\text{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = a \sin(x)$$\text{.}$', '["$-1/\\sqrt{1 - x^2}$", "$1/(x^2 + 1)$", "$1/\\sqrt{1 - x^2}$", "$\\sqrt{1 - x^2}$"]'::jsonb, 2, '$\text{Using}$ $\text{the}$ $\text{standard}$ $\text{derivative}$ $\text{formula}$ $\text{for}$ $\text{inverse}$ $\text{trigonometric}$ $\text{functions:}$ $\dfrac{d}{dx}[\arcsin(x)]$ $=$ $\frac{1}{\sqrt{1 - x^{2}}}$$\text{.}$', 'Inverse Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = a \cos(x)$$\text{.}$', '["$1/\\sqrt{1 - x^2}$", "$\\sqrt{1 - x^2}$", "$1/(x^2 + 1)$", "$-1/\\sqrt{1 - x^2}$"]'::jsonb, 3, '$\text{Using}$ $\text{the}$ $\text{standard}$ $\text{derivative}$ $\text{formula}$ $\text{for}$ $\text{inverse}$ $\text{trigonometric}$ $\text{functions:}$ $\dfrac{d}{dx}[\arccos(x)]$ $=$ $- \frac{1}{\sqrt{1 - x^{2}}}$$\text{.}$', 'Inverse Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = a \tan(x)$$\text{.}$', '["$\\sqrt{1 - x^2}$", "$1/(x^2 + 1)$", "$-1/(x^2 + 1)$", "$1/\\sqrt{1 - x^2}$"]'::jsonb, 1, '$\text{Using}$ $\text{the}$ $\text{standard}$ $\text{derivative}$ $\text{formula}$ $\text{for}$ $\text{inverse}$ $\text{trigonometric}$ $\text{functions:}$ $\dfrac{d}{dx}[\arctan(x)]$ $=$ $\frac{1}{x^{2} + 1}$$\text{.}$', 'Inverse Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{If}$ $f(x) = \ln(x^2 + 1)$$\text{,}$ $\text{find}$ $f''(2)$$\text{.}$', '["$4/3$", "$2/5$", "$1/5$", "$4/5$"]'::jsonb, 3, '$f''(x)$ $=$ $\dfrac{d}{dx}[\ln(u)]$ $=$ $\dfrac{u''}{u}$ $\text{with}$ $u = x^{2} + 1$$\text{:}$ $f''(x) = \frac{2 x}{x^{2} + 1}$$\text{.}$ $\text{At}$ $x=2$$\text{:}$ $f''(2)$ $=$ $\frac{2 \cdot 2}{2^{2} + 1}$ $=$ $\frac{4}{5}$$\text{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{If}$ $f(x) = e^{3x}$$\text{,}$ $\text{find}$ $f''(0)$$\text{.}$', '["$e^{3}$", "$0$", "$3$", "$1$"]'::jsonb, 2, '$f''(x)$ $=$ $\dfrac{d}{dx}[e^u]$ $=$ $e^u \cdot u''$ $\text{with}$ $u = 3 x$$\text{:}$ $f''(x) = 3 e^{3 x}$$\text{.}$ $\text{At}$ $x=0$$\text{:}$ $f''(0) = 3 e^{3 \cdot 0} = 3$$\text{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\int 1/x \, dx$$\text{.}$', '["$1/x^2 + C$", "$-1/x^2 + C$", "$ln|x| + C$", "$x \\cdot \\ln(x) + C$"]'::jsonb, 2, '$\text{With}$ $u = x$$\text{,}$ $du = 1 \, dx$$\text{.}$ $\int \dfrac{1}{x} \, dx$ $=$ $\int \dfrac{1}{u} \, du$ $=$ $\ln|u| + C$ $=$ $\ln|x| + C$$\text{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\int 2/(2x+1) \, dx$$\text{.}$', '["$2ln|2x+1| + C$", "$ln|x| + C$", "$(1/2)ln|2x+1| + C$", "$ln|2x+1| + C$"]'::jsonb, 3, '$\text{With}$ $u = 2 x + 1$$\text{,}$ $du = 2 \, dx$$\text{.}$ $\int \dfrac{2}{2 x + 1} \, dx$ $=$ $\int \dfrac{1}{u} \, du$ $=$ $\ln|u| + C$ $=$ $\ln|2 x + 1| + C$$\text{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\int e^{5x} \, dx$$\text{.}$', '["$(1/5)e^{5x} + C$", "$5e^{5x} + C$", "$e^{5x} + C$", "$e^{5x}/x + C$"]'::jsonb, 0, '$\text{With}$ $u = 5 x$$\text{,}$ $du = 5 \, dx$$\text{.}$ $\int e^{5 x} \, dx$ $=$ $\dfrac{1}{5} \int e^u \, du$ $=$ $\dfrac{1}{5} e^u + C$ $=$ $\dfrac{1}{5} e^{5 x} + C$$\text{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{substitution,}$ $\text{find}$ $\int (3x + 5)^4 \, dx$$\text{.}$', '["$81x^5/5$ $+$ $135x^4$ $+$ $450x^3$ $+$ $750x^2$ $+$ $625x$ $+$ $C$", "$243x^5/5$ $+$ $405x^4$ $+$ $1350x^3$ $+$ $2250x^2$ $+$ $1875x$ $+$ $C$", "$-81x^5/5$ $-$ $135x^4$ $-$ $450x^3$ $-$ $750x^2$ $-$ $625x$ $+$ $C$", "$324x^3 + 1620x^2 + 2700x + 1500 + C$"]'::jsonb, 0, '$\text{Let}$ $u = 3 x + 5$$\text{,}$ $\text{so}$ $du = 3 \, dx$$\text{.}$ $\int \left(3 x + 5\right)^{4} \, dx$ $=$ $\dfrac{1}{3} \int u^{4} \, du$ $=$ $\dfrac{1}{3} \cdot \dfrac{u^{5}}{5} + C$$\text{.}$ $\text{Substituting}$ $\text{back}$ $u = 3 x + 5$ $\text{and}$ $\text{expanding:}$ $\int \left(3 x + 5\right)^{4} \, dx$ $=$ $\frac{81 x^{5}}{5}$ $+$ $135 x^{4}$ $+$ $450 x^{3}$ $+$ $750 x^{2}$ $+$ $625 x$ $+$ $C$$\text{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{substitution,}$ $\text{find}$ $\int \cos(2x + 1) \, dx$$\text{.}$', '["$-\\sin(2x + 1)/2 + C$", "$3 \\sin(2x + 1)/2 + C$", "$\\sin(2x + 1)/2 + C$", "$-2 \\sin(2x + 1) + C$"]'::jsonb, 2, '$\text{Let}$ $u = 2 x + 1$$\text{,}$ $\text{so}$ $du = 2 \, dx$$\text{.}$ $\int \cos(2 x + 1) \, dx$ $=$ $\dfrac{1}{2} \int \cos(u) \, du$ $=$ $\dfrac{1}{2} \sin(u) + C$$\text{.}$ $\text{Substituting}$ $\text{back}$ $u = 2 x + 1$$\text{:}$ $\int \cos(2 x + 1) \, dx$ $=$ $\frac{\sin{\left(2 x + 1 \right)}}{2}$ $+$ $C$$\text{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{substitution,}$ $\text{find}$ $\int (4 - 3x)^3 \, dx$$\text{.}$', '["$-81x^2 + 216x - 144 + C$", "$-81x^4/4 + 108x^3 - 216x^2 + 192x + C$", "$27x^4/4 - 36x^3 + 72x^2 - 64x + C$", "$-27x^4/4 + 36x^3 - 72x^2 + 64x + C$"]'::jsonb, 3, '$\text{Let}$ $u = 4 - 3 x$$\text{,}$ $\text{so}$ $du = -3 \, dx$$\text{.}$ $\int \left(4 - 3 x\right)^{3} \, dx$ $=$ $\dfrac{1}{-3} \int u^{3} \, du$ $=$ $\dfrac{1}{-3} \cdot \dfrac{u^{4}}{4} + C$$\text{.}$ $\text{Substituting}$ $\text{back}$ $u = 4 - 3 x$ $\text{and}$ $\text{expanding:}$ $\int \left(4 - 3 x\right)^{3} \, dx$ $=$ $- \frac{27 x^{4}}{4}$ $+$ $36 x^{3}$ $-$ $72 x^{2}$ $+$ $64 x$ $+$ $C$$\text{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{substitution,}$ $\text{find}$ $\int \sin(5x) \, dx$$\text{.}$', '["$-3 \\cos(5x)/5 + C$", "$-\\cos(5x)/5 + C$", "$\\cos(5x)/5 + C$", "$5 \\cos(5x) + C$"]'::jsonb, 1, '$\text{Using}$ $\text{an}$ $\text{appropriate}$ $\text{substitution}$ $\text{for}$ $\text{the}$ $\text{inner}$ $\text{expression,}$ $\int \sin{\left(5 x \right)} \, dx$ $=$ $- \frac{\cos{\left(5 x \right)}}{5} + C$$\text{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{0}^{1} 2x(x^2 + 1)^3 \, dx$$\text{.}$', '["$15/4$", "$15/2$", "$-15/4$", "$19/4$"]'::jsonb, 0, '$\text{Using}$ $\text{substitution,}$ $\text{an}$ $\text{antiderivative}$ $\text{is}$ $F(x)$ $=$ $\frac{x^{8}}{4}$ $+$ $x^{6}$ $+$ $\frac{3 x^{4}}{2}$ $+$ $x^{2}$$\text{.}$ $\text{Evaluating}$ $\text{from}$ $x=0$ $\text{to}$ $x=1$$\text{:}$ $F(1) - F(0)$ $=$ $\frac{15}{4} - 0$ $=$ $\frac{15}{4}$$\text{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{0}^{pi/2} \sin(x)^2 \cos(x) \, dx$$\text{.}$', '["$2/3$", "$1/3$", "$-1/3$", "$4/3$"]'::jsonb, 1, '$\text{Using}$ $\text{substitution,}$ $\text{an}$ $\text{antiderivative}$ $\text{is}$ $F(x)$ $=$ $\frac{\sin^{3}{\left(x \right)}}{3}$$\text{.}$ $\text{Evaluating}$ $\text{from}$ $x=0$ $\text{to}$ $x=\frac{\pi}{2}$$\text{:}$ $F(\frac{\pi}{2}) - F(0)$ $=$ $\frac{1}{3} - 0$ $=$ $\frac{1}{3}$$\text{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{0}^{2} x/(x^2 + 4) \, dx$$\text{.}$', '["$3 \\log(2)/2$", "$-\\ln(2)/2$", "$\\ln(2)/2$", "$\\ln(2)$"]'::jsonb, 2, '$\text{Using}$ $\text{substitution,}$ $\text{an}$ $\text{antiderivative}$ $\text{is}$ $F(x)$ $=$ $\frac{\log{\left(x^{2} + 4 \right)}}{2}$$\text{.}$ $\text{Evaluating}$ $\text{from}$ $x=0$ $\text{to}$ $x=2$$\text{:}$ $F(2) - F(0)$ $=$ $\log{\left(2 \sqrt{2} \right)}$ $-$ $\log{\left(2 \right)}$ $=$ $\log{\left(\sqrt{2} \right)}$$\text{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{Integration}$ $\text{by}$ $\text{Parts,}$ $\text{find}$ $\int xe^{x} \, dx$$\text{.}$', '["$\\text{xe\\textasciicircum{}(x)}$ $\\text{+}$ $\\text{C}$", "$(1 - x)e^{x} + C$", "$(x - 1)e^{x} + C$", "$x^2e^{x}/2 + C$"]'::jsonb, 2, '$\text{With}$ $u = x$ $\text{and}$ $dv = e^{x} \, dx$$\text{:}$ $du = dx$ $\text{and}$ $v = e^{x}$$\text{.}$ $\text{Integration}$ $\text{by}$ $\text{parts,}$ $\int u \, dv = uv - \int v \, du$$\text{,}$ $\text{gives}$ $\int x e^{x} \, dx$ $=$ $xe^{x} - \int e^{x} \, dx$ $=$ $\left(x - 1\right) e^{x} + C$$\text{.}$', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{Integration}$ $\text{by}$ $\text{Parts,}$ $\text{find}$ $\int x \sin(x) \, dx$$\text{.}$', '["$-x \\cos(x) + \\sin(x) + C$", "$-x \\cos(x) + C$", "$-x^2 \\cos(x)/2 + C$", "$x \\cos(x) - \\sin(x) + C$"]'::jsonb, 0, '$\text{With}$ $u = x$ $\text{and}$ $dv = \sin{\left(x \right)} \, dx$$\text{:}$ $du = dx$ $\text{and}$ $v = - \cos{\left(x \right)}$$\text{.}$ $\text{Integration}$ $\text{by}$ $\text{parts,}$ $\int u \, dv = uv - \int v \, du$$\text{,}$ $\text{gives}$ $\int x \sin{\left(x \right)} \, dx$ $=$ $x- \cos{\left(x \right)}$ $-$ $\int$ $-$ $\cos{\left(x \right)} \, dx$ $=$ $- x \cos{\left(x \right)}$ $+$ $\sin{\left(x \right)}$ $+$ $C$$\text{.}$', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{Integration}$ $\text{by}$ $\text{Parts,}$ $\text{find}$ $\int x \cos(x) \, dx$$\text{.}$', '["$-x \\sin(x) - \\cos(x) + C$", "$x^2 \\sin(x)/2 + C$", "$x \\sin(x) + C$", "$x \\sin(x) + \\cos(x) + C$"]'::jsonb, 3, '$\text{With}$ $u = x$ $\text{and}$ $dv = \cos{\left(x \right)} \, dx$$\text{:}$ $du = dx$ $\text{and}$ $v = \sin{\left(x \right)}$$\text{.}$ $\text{Integration}$ $\text{by}$ $\text{parts,}$ $\int u \, dv = uv - \int v \, du$$\text{,}$ $\text{gives}$ $\int x \cos{\left(x \right)} \, dx$ $=$ $x\sin{\left(x \right)}$ $-$ $\int \sin{\left(x \right)} \, dx$ $=$ $x \sin{\left(x \right)}$ $+$ $\cos{\left(x \right)}$ $+$ $C$$\text{.}$', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{0}^{1} x \cdot e^x \, dx$$\text{.}$', '["$-1 + E$", "$\\text{E}$", "$0$", "$1$"]'::jsonb, 3, '$\text{Using}$ $\text{integration}$ $\text{by}$ $\text{parts}$ $\text{with}$ $u = x$$\text{,}$ $dv = e^{x} \, dx$$\text{:}$ $v = e^{x}$$\text{,}$ $\text{so}$ $\int x \, e^{x} \, dx$ $=$ $xe^{x} - \int e^{x} \, dx$ $=$ $\left(x - 1\right) e^{x} + C$$\text{.}$ $\text{Evaluating}$ $\text{from}$ $0$ $\text{to}$ $1$$\text{:}$ $(\left(-1 + 1\right) e^{1})$ $-$ $(\left(-1 + 0\right) e^{0})$ $=$ $0 - -1$ $=$ $1$$\text{.}$', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\int \tan(x) \, dx$$\text{.}$', '["$ln|\\sec(x)| + C$", "$ln|\\cos(x)| + C$", "$\\sec(x)\\tan(x) + C$", "$ln|\\sin(x)| + C$"]'::jsonb, 0, '$\text{Writing}$ $\tan(x) = \sin(x)/\cos(x)$ $\text{and}$ $\text{substituting}$ $v = \cos(x)$ $\text{(so}$ $dv = -\sin(x) \, dx$$\text{)}$ $\text{gives}$ $\int \tan(x) \, dx = -\ln|\cos(x)| + C$$\text{,}$ $\text{which}$ $\text{is}$ $\text{the}$ $\text{same}$ $\text{as}$ $\ln|\sec(x)| + C$ $\text{(since}$ $-\ln|\cos(x)|$ $=$ $\ln|\cos(x)|^{-1}$ $=$ $\ln|\sec(x)|$$\text{).}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Use}$ $\text{the}$ $\text{definition}$ $\text{of}$ $\text{the}$ $\text{derivative}$ $\text{(first}$ $\text{principles)}$ $\text{--}$ $\text{that}$ $\text{is,}$ $\text{f''(x)}$ $\text{as}$ $\text{the}$ $\text{limit,}$ $\text{as}$ $\text{h}$ $\text{approaches}$ $\text{0,}$ $\text{of}$ $\text{the}$ $\text{difference}$ $\text{quotient}$ $\text{[f(x+h)}$ $\text{-}$ $\text{f(x)]/h}$ $\text{--}$ $\text{to}$ $\text{find}$ $\text{f''(x)}$ $\text{for}$ $f(x) = x^2$$\text{.}$', '["$2x$", "$x^2$", "$2$", "$\\text{x}$"]'::jsonb, 0, '$\text{By}$ $\text{definition,}$ $f''(x)$ $=$ $\lim_{h \to 0} \dfrac{f(x+h) - f(x)}{h}$$\text{.}$ $\text{Here}$ $f(x+h) = (x+h)^2 = x^2 + 2xh + h^2$$\text{,}$ $\text{so}$ $\dfrac{f(x+h)-f(x)}{h}$ $=$ $\dfrac{2xh + h^2}{h}$ $=$ $2x + h$$\text{.}$ $\text{Letting}$ $h \to 0$ $\text{gives}$ $f''(x) = 2x$$\text{.}$', 'The Derivative as a Limit', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Use}$ $\text{the}$ $\text{definition}$ $\text{of}$ $\text{the}$ $\text{derivative}$ $\text{(first}$ $\text{principles)}$ $\text{to}$ $\text{find}$ $\text{f''(x)}$ $\text{for}$ $f(x) = 3x + 2$$\text{.}$', '["$3x$", "$2$", "$3$", "$0$"]'::jsonb, 2, '$f(x+h) = 3(x+h) + 2 = 3x + 3h + 2$$\text{,}$ $\text{so}$ $\dfrac{f(x+h) - f(x)}{h}$ $=$ $\dfrac{3h}{h}$ $=$ $3$ $\text{for}$ $\text{every}$ $h \neq 0$$\text{.}$ $\text{Letting}$ $h \to 0$$\text{,}$ $f''(x) = 3$ $\text{--}$ $\text{a}$ $\text{straight}$ $\text{line''s}$ $\text{slope}$ $\text{never}$ $\text{changes.}$', 'The Derivative as a Limit', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Use}$ $\text{first}$ $\text{principles}$ $\text{to}$ $\text{find}$ $\text{f''(x)}$ $\text{for}$ $f(x) = x^2 + 2x$$\text{,}$ $\text{then}$ $\text{evaluate}$ $f''(1)$$\text{.}$', '["$3$", "$4$", "$2$", "$1$"]'::jsonb, 1, '$f(x+h) - f(x)$ $=$ $(x+h)^{2} + 2(x+h) - x^{2} - 2x$ $=$ $2xh + h^{2} + 2h$$\text{,}$ $\text{so}$ $\dfrac{f(x+h)-f(x)}{h} = 2x + h + 2$$\text{.}$ $\text{Letting}$ $h \to 0$ $\text{gives}$ $f''(x) = 2x + 2$$\text{,}$ $\text{so}$ $f''(1) = 2(1) + 2 = 4$$\text{.}$', 'The Derivative as a Limit', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Use}$ $\text{first}$ $\text{principles}$ $\text{to}$ $\text{find}$ $\text{f''(x)}$ $\text{for}$ $f(x) = 1/x (x != 0)$$\text{.}$', '["$1/x^2$", "$-1/x^2$", "$-1/x$", "$1/x$"]'::jsonb, 1, '$\dfrac{f(x+h)-f(x)}{h}$ $=$ $\dfrac{1}{h}\left(\dfrac{1}{x+h} - \dfrac{1}{x}\right)$ $=$ $\dfrac{1}{h} \cdot \dfrac{x - (x+h)}{x(x+h)}$ $=$ $\dfrac{-h}{h \cdot x(x+h)}$ $=$ $\dfrac{-1}{x(x+h)}$$\text{.}$ $\text{Letting}$ $h \to 0$ $\text{gives}$ $f''(x) = -\dfrac{1}{x^{2}}$$\text{.}$', 'The Derivative as a Limit', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Use}$ $\text{first}$ $\text{principles}$ $\text{to}$ $\text{find}$ $\text{f''(x)}$ $\text{for}$ $f(x) = x^2 - 3x$$\text{,}$ $\text{then}$ $\text{evaluate}$ $f''(2)$$\text{.}$', '["$-1$", "$0$", "$1$", "$4$"]'::jsonb, 2, '$f(x+h) - f(x)$ $=$ $(x+h)^{2} - 3(x+h) - x^{2} + 3x$ $=$ $2xh + h^{2} - 3h$$\text{,}$ $\text{so}$ $\dfrac{f(x+h)-f(x)}{h} = 2x + h - 3$$\text{.}$ $\text{Letting}$ $h \to 0$ $\text{gives}$ $f''(x) = 2x - 3$$\text{,}$ $\text{so}$ $f''(2) = 2(2) - 3 = 1$$\text{.}$', 'The Derivative as a Limit', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{slope}$ $\text{of}$ $\text{the}$ $\text{line}$ $\text{tangent}$ $\text{to}$ $\text{the}$ $\text{curve}$ $y = x^3 at the point (1$$\text{,}$$1)$$\text{.}$', '["$1$", "$2$", "$3$", "$9$"]'::jsonb, 2, '$\text{The}$ $\text{slope}$ $\text{of}$ $\text{the}$ $\text{tangent}$ $\text{at}$ $x=x_0$ $\text{is}$ $y''(x_0)$$\text{.}$ $\text{Here}$ $y'' = 3x^{2}$$\text{,}$ $\text{so}$ $\text{at}$ $x_0=1$$\text{,}$ $\text{the}$ $\text{slope}$ $\text{is}$ $y''(1) = 3(1)^{2} = 3$$\text{.}$', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{equation}$ $\text{of}$ $\text{the}$ $\text{line}$ $\text{tangent}$ $\text{to}$ $\text{the}$ $\text{curve}$ $y = 3x^2 + 1 at the point (1$$\text{,}$$4)$$\text{.}$', '["$y = 6x - 2$", "$y = 3x + 1$", "$y = 6x + 4$", "$y = 2x + 2$"]'::jsonb, 0, '$y'' = 6x$$\text{,}$ $\text{so}$ $\text{the}$ $\text{slope}$ $\text{at}$ $(1,4)$ $\text{is}$ $y''(1) = 6$$\text{.}$ $\text{Using}$ $\text{the}$ $\text{point-slope}$ $\text{form}$ $y - y_0 = m(x - x_0)$ $\text{with}$ $m=6$$\text{,}$ $(x_0,y_0)=(1,4)$$\text{:}$ $y - 4 = 6(x - 1)$$\text{,}$ $\text{which}$ $\text{simplifies}$ $\text{to}$ $y = 6x - 2$$\text{.}$', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{equation}$ $\text{of}$ $\text{the}$ $\text{line}$ $\text{normal}$ $\text{to}$ $\text{the}$ $\text{curve}$ $y = x^3 + 1 at the point (-1$$\text{,}$$0)$$\text{.}$', '["$y = 3x + 3$", "$x + 3y = -1$", "$y = -3x - 3$", "$3x + y = -3$"]'::jsonb, 1, '$y'' = 3x^{2}$$\text{,}$ $\text{so}$ $\text{the}$ $\text{slope}$ $\text{of}$ $\text{the}$ $\text{tangent}$ $\text{at}$ $(-1,0)$ $\text{is}$ $y''(-1) = 3$$\text{.}$ $\text{The}$ $\text{normal}$ $\text{is}$ $\text{perpendicular}$ $\text{to}$ $\text{the}$ $\text{tangent,}$ $\text{so}$ $\text{its}$ $\text{slope}$ $\text{is}$ $-\dfrac{1}{3}$$\text{.}$ $\text{Using}$ $\text{point-slope}$ $\text{form:}$ $y - 0 = -\dfrac{1}{3}(x - (-1))$$\text{,}$ $\text{i.e.}$ $3y = -(x+1)$$\text{,}$ $\text{which}$ $\text{rearranges}$ $\text{to}$ $x + 3y = -1$$\text{.}$', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{slope}$ $\text{of}$ $\text{the}$ $\text{tangent}$ $\text{to}$ $\text{the}$ $\text{curve}$ $y = x^2 - 4x + 3 at the point (3$$\text{,}$$0)$$\text{.}$', '["$-2$", "$0$", "$2$", "$3$"]'::jsonb, 2, '$y'' = 2x - 4$$\text{,}$ $\text{so}$ $\text{at}$ $x=3$ $\text{the}$ $\text{slope}$ $\text{is}$ $y''(3) = 2(3) - 4 = 2$$\text{.}$', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{equation}$ $\text{of}$ $\text{the}$ $\text{line}$ $\text{normal}$ $\text{to}$ $\text{the}$ $\text{curve}$ $y = 1/x at the point (2$$\text{,}$ $1/2)$$\text{.}$', '["$y = 4x - 15/2$", "$y = -x/4 + 1$", "$x + 4y = 4$", "$y = 4x - 7$"]'::jsonb, 0, '$y'' = -\dfrac{1}{x^{2}}$$\text{,}$ $\text{so}$ $\text{the}$ $\text{tangent''s}$ $\text{slope}$ $\text{at}$ $(2,\tfrac{1}{2})$ $\text{is}$ $y''(2) = -\dfrac{1}{4}$$\text{.}$ $\text{The}$ $\text{normal''s}$ $\text{slope}$ $\text{is}$ $\text{the}$ $\text{negative}$ $\text{reciprocal,}$ $4$$\text{.}$ $\text{Point-slope}$ $\text{form}$ $\text{gives}$ $y - \dfrac{1}{2} = 4(x-2)$$\text{,}$ $\text{which}$ $\text{simplifies}$ $\text{to}$ $y = 4x - \dfrac{15}{2}$$\text{.}$', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{The}$ $\text{displacement}$ $\text{of}$ $\text{a}$ $\text{particle}$ $\text{moving}$ $\text{along}$ $\text{a}$ $\text{line}$ $\text{is}$ $\text{s(t)}$ $\text{=}$ $\text{t\textasciicircum{}3}$ $\text{-}$ $\text{6t\textasciicircum{}2}$ $\text{+}$ $\text{9t.}$ $\text{Find}$ $\text{its}$ $\text{velocity}$ $\text{at}$ $\text{t}$ $\text{=}$ $\text{2.}$', '["$-3$", "$0$", "$3$", "$6$"]'::jsonb, 0, '$\text{Velocity}$ $\text{is}$ $v(t) = s''(t) = 3t^{2} - 12t + 9$$\text{.}$ $\text{At}$ $t=2$$\text{:}$ $v(2)$ $=$ $3(2)^{2} - 12(2) + 9$ $=$ $12 - 24 + 9$ $=$ $-3$$\text{.}$', 'Velocity and Acceleration', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{For}$ $\text{the}$ $\text{displacement}$ $\text{s(t)}$ $\text{=}$ $\text{t\textasciicircum{}3}$ $\text{-}$ $\text{6t\textasciicircum{}2}$ $\text{+}$ $\text{9t,}$ $\text{find}$ $\text{the}$ $\text{acceleration}$ $\text{at}$ $\text{t}$ $\text{=}$ $\text{1.}$', '["$-6$", "$0$", "$6$", "$12$"]'::jsonb, 0, '$\text{Acceleration}$ $\text{is}$ $a(t) = v''(t) = s''''(t) = 6t - 12$$\text{.}$ $\text{At}$ $t=1$$\text{:}$ $a(1) = 6(1) - 12 = -6$$\text{.}$', 'Velocity and Acceleration', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{A}$ $\text{ball}$ $\text{thrown}$ $\text{upward}$ $\text{has}$ $\text{height}$ $\text{s(t)}$ $\text{=}$ $\text{16t}$ $\text{-}$ $\text{t\textasciicircum{}2}$ $\text{(metres,}$ $\text{t}$ $\text{in}$ $\text{seconds).}$ $\text{At}$ $\text{what}$ $\text{time}$ $\text{does}$ $\text{the}$ $\text{ball}$ $\text{reach}$ $\text{its}$ $\text{maximum}$ $\text{height}$ $\text{(v}$ $\text{=}$ $\text{0)?}$', '["$t = 4$", "$t = 8$", "$t = 16$", "$t = 32$"]'::jsonb, 1, '$\text{Velocity}$ $\text{is}$ $v(t) = s''(t) = 16 - 2t$$\text{.}$ $\text{The}$ $\text{ball}$ $\text{is}$ $\text{at}$ $\text{its}$ $\text{highest}$ $\text{point}$ $\text{when}$ $v(t)=0$$\text{:}$ $16 - 2t = 0 \Rightarrow t = 8$$\text{.}$', 'Velocity and Acceleration', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{An}$ $\text{object''s}$ $\text{position}$ $\text{is}$ $\text{s(t)}$ $\text{=}$ $\text{t\textasciicircum{}2}$ $\text{-}$ $\text{4t}$ $\text{+}$ $\text{3.}$ $\text{At}$ $\text{what}$ $\text{time}$ $\text{t}$ $\text{is}$ $\text{the}$ $\text{object}$ $\text{momentarily}$ $\text{at}$ $\text{rest}$ $\text{(v}$ $\text{=}$ $\text{0)?}$', '["$t = 1$", "$t = 2$", "$t = 3$", "$t = 4$"]'::jsonb, 1, '$v(t) = s''(t) = 2t - 4$$\text{.}$ $\text{Setting}$ $v(t) = 0$$\text{:}$ $2t - 4 = 0 \Rightarrow t = 2$$\text{.}$', 'Velocity and Acceleration', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{The}$ $\text{velocity}$ $\text{of}$ $\text{a}$ $\text{particle}$ $\text{is}$ $\text{v(t)}$ $\text{=}$ $\text{3t\textasciicircum{}2}$ $\text{-}$ $\text{6t.}$ $\text{Find}$ $\text{its}$ $\text{acceleration}$ $\text{at}$ $\text{t}$ $\text{=}$ $\text{2.}$', '["$0$", "$6$", "$12$", "$18$"]'::jsonb, 1, '$\text{Acceleration}$ $\text{is}$ $a(t) = v''(t) = 6t - 6$$\text{.}$ $\text{At}$ $t=2$$\text{:}$ $a(2) = 6(2) - 6 = 6$$\text{.}$', 'Velocity and Acceleration', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{second}$ $\text{derivative}$ $\text{f''''(x)}$ $\text{for}$ $f(x) = x^4 - 3x^2$$\text{.}$', '["$4x^3 - 6x$", "$12x^2 - 6$", "$12x^2 - 3$", "$24x$"]'::jsonb, 1, '$f''(x) = 4x^{3} - 6x$$\text{.}$ $\text{Differentiating}$ $\text{again,}$ $f''''(x) = 12x^{2} - 6$$\text{.}$', 'Higher Order Derivatives', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{third}$ $\text{derivative}$ $\text{f''''''(x)}$ $\text{for}$ $f(x) = \sin(x)$$\text{.}$', '["$-\\cos(x)$", "$\\cos(x)$", "$-\\sin(x)$", "$\\sin(x)$"]'::jsonb, 0, '$f''(x) = \cos(x)$$\text{,}$ $f''''(x) = -\sin(x)$$\text{,}$ $\text{and}$ $\text{differentiating}$ $\text{once}$ $\text{more,}$ $f''''''(x) = -\cos(x)$$\text{.}$', 'Higher Order Derivatives', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $f''''(1)$ $\text{for}$ $f(x) = x^3 - 2x$$\text{.}$', '["$1$", "$2$", "$6$", "$-2$"]'::jsonb, 2, '$f''(x) = 3x^{2} - 2$$\text{,}$ $\text{so}$ $f''''(x) = 6x$$\text{.}$ $\text{At}$ $x=1$$\text{:}$ $f''''(1) = 6(1) = 6$$\text{.}$', 'Higher Order Derivatives', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{second}$ $\text{derivative}$ $\text{of}$ $f(x) = e^{2x}$$\text{.}$', '["$2e^{2x}$", "$4e^{2x}$", "$e^{2x}$", "$4e^x$"]'::jsonb, 1, '$f''(x) = 2 e^{2x}$ $\text{by}$ $\text{the}$ $\text{chain}$ $\text{rule.}$ $\text{Differentiating}$ $\text{again,}$ $f''''(x) = 2 \cdot 2 e^{2x} = 4 e^{2x}$$\text{.}$', 'Higher Order Derivatives', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{second}$ $\text{derivative}$ $\text{of}$ $f(x) = \ln(x)$$\text{,}$ $\text{for}$ $x > 0.$', '["$1/x^2$", "$-1/x^2$", "$-1/x$", "$1/x$"]'::jsonb, 1, '$f''(x) = \dfrac{1}{x}$$\text{.}$ $\text{Differentiating}$ $x^{-1}$ $\text{again}$ $\text{gives}$ $f''''(x) = -x^{-2} = -\dfrac{1}{x^{2}}$$\text{.}$', 'Higher Order Derivatives', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{For}$ $f(x) = x^3 - 3x$$\text{,}$ $\text{use}$ $\text{the}$ $\text{first}$ $\text{derivative}$ $\text{test}$ $\text{to}$ $\text{determine}$ $\text{the}$ $\text{nature}$ $\text{of}$ $\text{the}$ $\text{critical}$ $\text{point}$ $\text{at}$ $\text{x}$ $\text{=}$ $\text{-1.}$', '["$\\text{relative}$ $\\text{maximum}$", "$\\text{relative}$ $\\text{minimum}$", "$\\text{point}$ $\\text{of}$ $\\text{inflection}$", "$\\text{not}$ $\\text{a}$ $\\text{critical}$ $\\text{point}$"]'::jsonb, 0, '$f''(x) = 3x^{2} - 3 = 3(x-1)(x+1)$$\text{,}$ $\text{so}$ $\text{the}$ $\text{critical}$ $\text{points}$ $\text{are}$ $x=-1$ $\text{and}$ $x=1$$\text{.}$ $\text{For}$ $x$ $\text{slightly}$ $\text{less}$ $\text{than}$ $-1$$\text{,}$ $f''(x) > 0$ $\text{(increasing);}$ $\text{for}$ $x$ $\text{slightly}$ $\text{greater}$ $\text{than}$ $-1$$\text{,}$ $f''(x) < 0$ $\text{(decreasing).}$ $\text{Since}$ $f''$ $\text{changes}$ $\text{from}$ $\text{positive}$ $\text{to}$ $\text{negative,}$ $x=-1$ $\text{is}$ $\text{a}$ $\text{relative}$ $\text{maximum.}$', 'Extrema of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{For}$ $f(x) = 2x^3 - 3x^2 + 2$$\text{,}$ $\text{use}$ $\text{the}$ $\text{second}$ $\text{derivative}$ $\text{test}$ $\text{to}$ $\text{classify}$ $\text{the}$ $\text{critical}$ $\text{point}$ $\text{at}$ $\text{x}$ $\text{=}$ $\text{1.}$', '["$\\text{relative}$ $\\text{minimum}$", "$\\text{relative}$ $\\text{maximum}$", "$\\text{neither}$ $\\text{(}$$f''''(1)$ $= 0)$", "$\\text{not}$ $\\text{a}$ $\\text{critical}$ $\\text{point}$"]'::jsonb, 0, '$f''(x) = 6x^{2} - 6x = 6x(x-1)$$\text{,}$ $\text{so}$ $x=1$ $\text{is}$ $\text{a}$ $\text{critical}$ $\text{point.}$ $f''''(x) = 12x - 6$$\text{,}$ $\text{so}$ $f''''(1) = 12(1) - 6 = 6 > 0$$\text{.}$ $\text{Since}$ $f''''(1) > 0$$\text{,}$ $\text{the}$ $\text{second}$ $\text{derivative}$ $\text{test}$ $\text{says}$ $x=1$ $\text{is}$ $\text{a}$ $\text{relative}$ $\text{minimum.}$', 'Extrema of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{absolute}$ $\text{minimum}$ $\text{value}$ $\text{of}$ $f(x)$ $=$ $x^2 - 4x + 3 on the closed interval [0$$\text{,}$$5]$$\text{.}$', '["$-1$", "$0$", "$3$", "$8$"]'::jsonb, 0, '$f''(x) = 2x - 4 = 0$ $\text{at}$ $x=2$$\text{,}$ $\text{an}$ $\text{interior}$ $\text{critical}$ $\text{point.}$ $\text{Checking}$ $f$ $\text{at}$ $\text{the}$ $\text{critical}$ $\text{point}$ $\text{and}$ $\text{both}$ $\text{endpoints:}$ $f(0)=3$$\text{,}$ $f(2) = 4-8+3=-1$$\text{,}$ $f(5) = 25-20+3=8$$\text{.}$ $\text{The}$ $\text{smallest}$ $\text{of}$ $\text{these}$ $\text{is}$ $f(2) = -1$$\text{,}$ $\text{so}$ $\text{the}$ $\text{absolute}$ $\text{minimum}$ $\text{on}$ $[0,5]$ $\text{is}$ $-1$$\text{.}$', 'Extrema of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{For}$ $f(x) = x^3 - 3x^2$$\text{,}$ $\text{use}$ $\text{the}$ $\text{second}$ $\text{derivative}$ $\text{test}$ $\text{to}$ $\text{classify}$ $\text{the}$ $\text{critical}$ $\text{point}$ $\text{at}$ $\text{x}$ $\text{=}$ $\text{2.}$', '["$\\text{relative}$ $\\text{minimum}$", "$\\text{relative}$ $\\text{maximum}$", "$\\text{neither}$", "$\\text{cannot}$ $\\text{be}$ $\\text{determined}$"]'::jsonb, 0, '$f''(x) = 3x^{2} - 6x = 3x(x-2)$$\text{,}$ $\text{so}$ $x=0$ $\text{and}$ $x=2$ $\text{are}$ $\text{critical}$ $\text{points.}$ $f''''(x) = 6x - 6$$\text{,}$ $\text{so}$ $f''''(2) = 6(2) - 6 = 6 > 0$$\text{,}$ $\text{meaning}$ $x=2$ $\text{is}$ $\text{a}$ $\text{relative}$ $\text{minimum}$ $\text{by}$ $\text{the}$ $\text{second}$ $\text{derivative}$ $\text{test.}$', 'Extrema of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{For}$ $f(x) = x^4 - 4x^2$$\text{,}$ $\text{the}$ $\text{second}$ $\text{derivative}$ $\text{test}$ $\text{is}$ $\text{inconclusive}$ $\text{or}$ $\text{gives}$ $\text{a}$ $\text{maximum}$ $\text{at}$ $\text{one}$ $\text{of}$ $\text{its}$ $\text{critical}$ $\text{points.}$ $\text{What}$ $\text{does}$ $f''''(0)$ $\text{indicate}$ $\text{about}$ $\text{x}$ $\text{=}$ $\text{0?}$', '["$\\text{relative}$ $\\text{maximum}$", "$\\text{relative}$ $\\text{minimum}$", "$f''''(0)$ $= 0$$\\text{,}$ $\\text{so}$ $\\text{the}$ $\\text{test}$ $\\text{fails}$ $\\text{here}$", "$\\text{x=0}$ $\\text{is}$ $\\text{not}$ $\\text{a}$ $\\text{critical}$ $\\text{point}$"]'::jsonb, 0, '$f''(x) = 4x^{3} - 8x = 4x(x^{2}-2)$$\text{,}$ $\text{so}$ $\text{the}$ $\text{critical}$ $\text{points}$ $\text{are}$ $x=0, \sqrt{2}, -\sqrt{2}$$\text{.}$ $f''''(x) = 12x^{2} - 8$$\text{,}$ $\text{so}$ $f''''(0) = -8 < 0$$\text{.}$ $\text{Since}$ $f''''(0) < 0$$\text{,}$ $\text{the}$ $\text{second}$ $\text{derivative}$ $\text{test}$ $\text{says}$ $x=0$ $\text{is}$ $\text{a}$ $\text{relative}$ $\text{maximum.}$', 'Extrema of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{A}$ $\text{curve}$ $\text{is}$ $\text{symmetric}$ $\text{about}$ $\text{the}$ $\text{y-axis}$ $\text{if}$ $\text{replacing}$ $\text{x}$ $\text{by}$ $\text{-x}$ $\text{leaves}$ $\text{its}$ $\text{equation}$ $\text{unchanged.}$ $\text{Determine}$ $\text{the}$ $\text{symmetry}$ $\text{of}$ $y = x^4 - 3x^2 + 1$$\text{.}$', '["$\\text{symmetric}$ $\\text{about}$ $\\text{the}$ $\\text{y-axis}$", "$\\text{symmetric}$ $\\text{about}$ $\\text{the}$ $\\text{x-axis}$", "$\\text{symmetric}$ $\\text{about}$ $\\text{the}$ $\\text{origin}$", "$\\text{no}$ $\\text{symmetry}$"]'::jsonb, 0, '$\text{Replace}$ $x$ $\text{by}$ $-x$$\text{:}$ $(-x)^{4} - 3(-x)^{2} + 1$ $=$ $x^{4} - 3x^{2} + 1$$\text{,}$ $\text{which}$ $\text{is}$ $\text{identical}$ $\text{to}$ $\text{the}$ $\text{original}$ $\text{equation.}$ $\text{Since}$ $\text{the}$ $\text{equation}$ $\text{is}$ $\text{unchanged}$ $\text{when}$ $x$ $\text{is}$ $\text{replaced}$ $\text{by}$ $-x$$\text{,}$ $\text{the}$ $\text{curve}$ $\text{is}$ $\text{symmetric}$ $\text{about}$ $\text{the}$ $\text{y-axis.}$', 'Symmetry and Intercepts of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{A}$ $\text{curve}$ $\text{is}$ $\text{symmetric}$ $\text{about}$ $\text{the}$ $\text{origin}$ $\text{if}$ $\text{replacing}$ $\text{both}$ $\text{x}$ $\text{by}$ $\text{-x}$ $\text{and}$ $\text{y}$ $\text{by}$ $\text{-y}$ $\text{leaves}$ $\text{its}$ $\text{equation}$ $\text{unchanged.}$ $\text{Determine}$ $\text{the}$ $\text{symmetry}$ $\text{of}$ $\text{xy}$ $\text{=}$ $\text{4.}$', '["$\\text{symmetric}$ $\\text{about}$ $\\text{the}$ $\\text{origin}$", "$\\text{symmetric}$ $\\text{about}$ $\\text{the}$ $\\text{y-axis}$", "$\\text{symmetric}$ $\\text{about}$ $\\text{the}$ $\\text{x-axis}$", "$\\text{no}$ $\\text{symmetry}$"]'::jsonb, 0, '$\text{Replace}$ $x$ $\text{by}$ $-x$ $\text{and}$ $y$ $\text{by}$ $-y$$\text{:}$ $(-x)(-y) = xy$$\text{,}$ $\text{which}$ $\text{equals}$ $\text{the}$ $\text{original}$ $\text{left-hand}$ $\text{side.}$ $\text{Since}$ $\text{the}$ $\text{equation}$ $xy=4$ $\text{is}$ $\text{unchanged}$ $\text{under}$ $\text{this}$ $\text{replacement,}$ $\text{the}$ $\text{curve}$ $\text{is}$ $\text{symmetric}$ $\text{about}$ $\text{the}$ $\text{origin.}$', 'Symmetry and Intercepts of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{x-intercepts}$ $\text{of}$ $\text{the}$ $\text{graph}$ $\text{of}$ $y = x^2 - 5x + 6$$\text{.}$', '["$\\text{x}$ $\\text{=}$ $\\text{2}$ $\\text{and}$ $\\text{x}$ $\\text{=}$ $\\text{3}$", "$\\text{x}$ $\\text{=}$ $\\text{-2}$ $\\text{and}$ $\\text{x}$ $\\text{=}$ $\\text{-3}$", "$\\text{x}$ $\\text{=}$ $\\text{1}$ $\\text{and}$ $\\text{x}$ $\\text{=}$ $\\text{6}$", "$\\text{x}$ $\\text{=}$ $\\text{0}$ $\\text{and}$ $\\text{x}$ $\\text{=}$ $\\text{6}$"]'::jsonb, 0, '$\text{The}$ $\text{x-intercepts}$ $\text{satisfy}$ $y=0$$\text{:}$ $x^{2} - 5x + 6 = 0$$\text{,}$ $\text{which}$ $\text{factors}$ $\text{as}$ $(x-2)(x-3) = 0$$\text{,}$ $\text{giving}$ $x=2$ $\text{or}$ $x=3$$\text{.}$', 'Symmetry and Intercepts of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{A}$ $\text{curve}$ $y = f(x) is symmetric$ $\text{about}$ $\text{the}$ $\text{origin}$ $\text{if}$ $\text{f(-x)}$ $\text{=}$ $\text{-f(x)}$ $\text{(an}$ $\text{odd}$ $\text{function).}$ $\text{Determine}$ $\text{the}$ $\text{symmetry}$ $\text{of}$ $y = x^3 - x$$\text{.}$', '["$\\text{symmetric}$ $\\text{about}$ $\\text{the}$ $\\text{origin}$", "$\\text{symmetric}$ $\\text{about}$ $\\text{the}$ $\\text{y-axis}$", "$\\text{symmetric}$ $\\text{about}$ $\\text{the}$ $\\text{x-axis}$", "$\\text{no}$ $\\text{symmetry}$"]'::jsonb, 0, '$\text{Replace}$ $x$ $\text{by}$ $-x$$\text{:}$ $(-x)^{3} - (-x)$ $=$ $-x^{3} + x$ $=$ $-(x^{3}-x)$$\text{.}$ $\text{Since}$ $\text{this}$ $\text{equals}$ $\text{the}$ $\text{negative}$ $\text{of}$ $\text{the}$ $\text{original}$ $\text{expression,}$ $\text{i.e.}$ $f(-x) = -f(x)$$\text{,}$ $\text{the}$ $\text{function}$ $\text{is}$ $\text{odd}$ $\text{and}$ $\text{its}$ $\text{graph}$ $\text{is}$ $\text{symmetric}$ $\text{about}$ $\text{the}$ $\text{origin.}$', 'Symmetry and Intercepts of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{y-intercepts}$ $\text{of}$ $\text{the}$ $\text{graph}$ $\text{of}$ $\text{x\textasciicircum{}2}$ $\text{+}$ $\text{y\textasciicircum{}2}$ $\text{=}$ $\text{9.}$', '["$y = -3 and y = 3$", "$y = -9 and y = 9$", "$y = 0 only$", "$y = 3 only$"]'::jsonb, 0, '$\text{Set}$ $x=0$$\text{:}$ $0 + y^{2} = 9$$\text{,}$ $\text{so}$ $y^{2} = 9$$\text{,}$ $\text{giving}$ $y = 3$ $\text{or}$ $y = -3$$\text{.}$', 'Symmetry and Intercepts of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{horizontal}$ $\text{asymptote}$ $\text{of}$ $\text{the}$ $\text{graph}$ $\text{of}$ $y = (x - 1)/(x + 2)$$\text{.}$', '["$y = 1$", "$y = -1$", "$y = 0$", "$y = 2$"]'::jsonb, 0, '$\text{For}$ $\text{a}$ $\text{rational}$ $\text{function,}$ $\text{the}$ $\text{horizontal}$ $\text{asymptote}$ $\text{is}$ $\lim_{x \to \infty} \dfrac{x-1}{x+2}$$\text{.}$ $\text{Dividing}$ $\text{numerator}$ $\text{and}$ $\text{denominator}$ $\text{by}$ $x$$\text{:}$ $\dfrac{1 - 1/x}{1 + 2/x} \to \dfrac{1}{1}$ $=$ $1$ $\text{as}$ $x \to \infty$$\text{.}$ $\text{So}$ $y=1$ $\text{is}$ $\text{the}$ $\text{horizontal}$ $\text{asymptote.}$', 'Asymptotes of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{horizontal}$ $\text{asymptote}$ $\text{of}$ $\text{the}$ $\text{graph}$ $\text{of}$ $y = (2x^2 + 1)/(x^2 - 4)$$\text{.}$', '["$y = 2$", "$y = 1$", "$y = -4$", "$y = 0$"]'::jsonb, 0, '$\text{Since}$ $\text{the}$ $\text{numerator}$ $\text{and}$ $\text{denominator}$ $\text{have}$ $\text{the}$ $\text{same}$ $\text{degree,}$ $\text{the}$ $\text{horizontal}$ $\text{asymptote}$ $\text{is}$ $\text{the}$ $\text{ratio}$ $\text{of}$ $\text{leading}$ $\text{coefficients:}$ $y = \dfrac{2}{1} = 2$$\text{,}$ $\text{confirmed}$ $\text{by}$ $\lim_{x \to \infty} \dfrac{2x^{2}+1}{x^{2}-4}$ $=$ $2$$\text{.}$', 'Asymptotes of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{vertical}$ $\text{asymptotes}$ $\text{of}$ $\text{the}$ $\text{graph}$ $\text{of}$ $y = 1/(x^2 - 9)$$\text{.}$', '["$\\text{x}$ $\\text{=}$ $\\text{3}$ $\\text{and}$ $\\text{x}$ $\\text{=}$ $\\text{-3}$", "$\\text{x}$ $\\text{=}$ $\\text{9}$ $\\text{and}$ $\\text{x}$ $\\text{=}$ $\\text{-9}$", "$x = 0$", "$\\text{there}$ $\\text{are}$ $\\text{none}$"]'::jsonb, 0, '$\text{Vertical}$ $\text{asymptotes}$ $\text{of}$ $\text{a}$ $\text{proper}$ $\text{rational}$ $\text{function}$ $\text{occur}$ $\text{where}$ $\text{the}$ $\text{denominator}$ $\text{is}$ $\text{zero}$ $\text{(and}$ $\text{the}$ $\text{numerator}$ $\text{is}$ $\text{not):}$ $x^{2} - 9 = 0 \Rightarrow x = 3$ $\text{or}$ $x=-3$$\text{.}$', 'Asymptotes of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{horizontal}$ $\text{asymptote}$ $\text{of}$ $\text{the}$ $\text{graph}$ $\text{of}$ $y = (3x + 1)/(x - 5)$$\text{.}$', '["$y = 3$", "$y = -1/5$", "$y = 5$", "$y = 1$"]'::jsonb, 0, '$\text{Dividing}$ $\text{numerator}$ $\text{and}$ $\text{denominator}$ $\text{by}$ $x$$\text{:}$ $\dfrac{3 + 1/x}{1 - 5/x} \to \dfrac{3}{1}$ $=$ $3$ $\text{as}$ $x \to \infty$$\text{.}$ $\text{So}$ $y=3$ $\text{is}$ $\text{the}$ $\text{horizontal}$ $\text{asymptote.}$', 'Asymptotes of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{vertical}$ $\text{asymptote}$ $\text{of}$ $\text{the}$ $\text{graph}$ $\text{of}$ $y = (x + 1)/(x - 3)$$\text{.}$', '["$x = 3$", "$x = -1$", "$x = -3$", "$y = 1$"]'::jsonb, 0, '$\text{The}$ $\text{denominator}$ $\text{vanishes}$ $\text{at}$ $x = 3$ $\text{(and}$ $\text{the}$ $\text{numerator,}$ $x+1=4$$\text{,}$ $\text{does}$ $\text{not),}$ $\text{so}$ $x = 3$ $\text{is}$ $\text{a}$ $\text{vertical}$ $\text{asymptote.}$', 'Asymptotes of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\lim_{x \to 0^+} [|x|/x]$$\text{,}$ $\text{the}$ $\text{right-hand}$ $\text{limit}$ $\text{as}$ $\text{x}$ $\text{approaches}$ $\text{0.}$', '["$1$", "$-1$", "$0$", "$\\text{the}$ $\\text{limit}$ $\\text{does}$ $\\text{not}$ $\\text{exist}$"]'::jsonb, 0, '$\text{For}$ $x > 0$$\text{,}$ $|x| = x$$\text{,}$ $\text{so}$ $\dfrac{|x|}{x} = \dfrac{x}{x} = 1$ $\text{for}$ $\text{every}$ $x>0$$\text{.}$ $\text{Hence}$ $\lim_{x \to 0^+} \dfrac{|x|}{x} = 1$$\text{.}$', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\lim_{x \to 0^-} [|x|/x]$$\text{,}$ $\text{the}$ $\text{left-hand}$ $\text{limit}$ $\text{as}$ $\text{x}$ $\text{approaches}$ $\text{0.}$', '["$-1$", "$1$", "$0$", "$\\text{the}$ $\\text{limit}$ $\\text{does}$ $\\text{not}$ $\\text{exist}$"]'::jsonb, 0, '$\text{For}$ $x < 0$$\text{,}$ $|x| = -x$$\text{,}$ $\text{so}$ $\dfrac{|x|}{x} = \dfrac{-x}{x} = -1$ $\text{for}$ $\text{every}$ $x<0$$\text{.}$ $\text{Hence}$ $\lim_{x \to 0^-} \dfrac{|x|}{x} = -1$$\text{.}$', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\lim_{x \to 3^+} [(x-3)/|x-3|]$$\text{.}$', '["$1$", "$-1$", "$0$", "$\\text{does}$ $\\text{not}$ $\\text{exist}$"]'::jsonb, 0, '$\text{For}$ $x > 3$$\text{,}$ $x - 3 > 0$ $\text{so}$ $|x-3| = x-3$$\text{,}$ $\text{giving}$ $\dfrac{x-3}{|x-3|} = 1$ $\text{for}$ $\text{every}$ $x$ $\text{just}$ $\text{above}$ $3$$\text{.}$ $\text{Hence}$ $\lim_{x \to 3^+} \dfrac{x-3}{|x-3|} = 1$$\text{.}$', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{A}$ $\text{function}$ $\text{f}$ $\text{is}$ $\text{defined}$ $\text{by}$ $f(x) = x+1$ $\text{for}$ $x<1$ $\text{and}$ $f(x) = 4-x$ $\text{for}$ $\text{x}$ $\text{greater}$ $\text{than}$ $\text{or}$ $\text{equal}$ $\text{to}$ $\text{1.}$ $\text{Find}$ $\lim_{x \to 1^-} [f(x)]$$\text{.}$', '["$2$", "$3$", "$1$", "$4$"]'::jsonb, 0, '$\text{For}$ $x < 1$$\text{,}$ $f(x) = x+1$$\text{,}$ $\text{so}$ $\text{the}$ $\text{left-hand}$ $\text{limit}$ $\text{uses}$ $\text{this}$ $\text{branch:}$ $\lim_{x \to 1^-} (x+1) = 1 + 1 = 2$$\text{.}$', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{A}$ $\text{function}$ $\text{f}$ $\text{is}$ $\text{defined}$ $\text{by}$ $f(x) = x+1$ $\text{for}$ $x<1$ $\text{and}$ $f(x) = 4-x$ $\text{for}$ $\text{x}$ $\text{greater}$ $\text{than}$ $\text{or}$ $\text{equal}$ $\text{to}$ $\text{1.}$ $\text{Find}$ $\lim_{x \to 1^+} [f(x)]$$\text{.}$', '["$3$", "$2$", "$1$", "$4$"]'::jsonb, 0, '$\text{For}$ $x \geq 1$$\text{,}$ $f(x) = 4-x$$\text{,}$ $\text{so}$ $\text{the}$ $\text{right-hand}$ $\text{limit}$ $\text{uses}$ $\text{this}$ $\text{branch:}$ $\lim_{x \to 1^+} (4-x) = 4 - 1 = 3$$\text{.}$', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 0} [1/x^2]$$\text{.}$', '["$\\text{infinity}$", "$0$", "$1$", "$\\text{the}$ $\\text{limit}$ $\\text{does}$ $\\text{not}$ $\\text{exist}$ $\\text{and}$ $\\text{is}$ $\\text{not}$ $\\text{infinite}$"]'::jsonb, 0, '$\text{As}$ $x \to 0$ $\text{from}$ $\text{either}$ $\text{side,}$ $x^{2} \to 0^{+}$ $\text{(always}$ $\text{positive),}$ $\text{so}$ $\dfrac{1}{x^{2}}$ $\text{grows}$ $\text{without}$ $\text{bound.}$ $\text{Hence}$ $\lim_{x \to 0} \dfrac{1}{x^{2}} = \infty$$\text{.}$', 'Infinite Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 2^+} [1/(x-2)]$$\text{.}$', '["$\\text{infinity}$", "$\\text{negative}$ $\\text{infinity}$", "$0$", "$1$"]'::jsonb, 0, '$\text{As}$ $x \to 2^{+}$$\text{,}$ $x-2 \to 0^{+}$ $\text{(a}$ $\text{small}$ $\text{positive}$ $\text{number),}$ $\text{so}$ $\dfrac{1}{x-2}$ $\text{grows}$ $\text{without}$ $\text{bound}$ $\text{through}$ $\text{positive}$ $\text{values.}$ $\text{Hence}$ $\lim_{x \to 2^+} \dfrac{1}{x-2} = \infty$$\text{.}$', 'Infinite Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 2^-} [1/(x-2)]$$\text{.}$', '["$\\text{negative}$ $\\text{infinity}$", "$\\text{infinity}$", "$0$", "$-1$"]'::jsonb, 0, '$\text{As}$ $x \to 2^{-}$$\text{,}$ $x-2 \to 0^{-}$ $\text{(a}$ $\text{small}$ $\text{negative}$ $\text{number),}$ $\text{so}$ $\dfrac{1}{x-2}$ $\text{decreases}$ $\text{without}$ $\text{bound}$ $\text{through}$ $\text{negative}$ $\text{values.}$ $\text{Hence}$ $\lim_{x \to 2^-} \dfrac{1}{x-2}$ $=$ $-\infty$$\text{.}$', 'Infinite Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 3} [1/(x-3)^2]$$\text{.}$', '["$\\text{infinity}$", "$\\text{negative}$ $\\text{infinity}$", "$0$", "$\\text{does}$ $\\text{not}$ $\\text{exist}$ $\\text{and}$ $\\text{is}$ $\\text{not}$ $\\text{infinite}$"]'::jsonb, 0, '$\text{As}$ $x \to 3$ $\text{from}$ $\text{either}$ $\text{side,}$ $(x-3)^{2} \to 0^{+}$ $\text{(a}$ $\text{square}$ $\text{is}$ $\text{never}$ $\text{negative),}$ $\text{so}$ $\dfrac{1}{(x-3)^{2}}$ $\text{grows}$ $\text{without}$ $\text{bound}$ $\text{through}$ $\text{positive}$ $\text{values.}$ $\text{Hence}$ $\lim_{x \to 3} \dfrac{1}{(x-3)^{2}}$ $=$ $\infty$$\text{.}$', 'Infinite Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 0} [-1/x^4]$$\text{.}$', '["$\\text{negative}$ $\\text{infinity}$", "$\\text{infinity}$", "$0$", "$-1$"]'::jsonb, 0, '$\text{As}$ $x \to 0$$\text{,}$ $x^{4} \to 0^{+}$$\text{,}$ $\text{so}$ $\dfrac{1}{x^{4}} \to \infty$ $\text{and}$ $\text{therefore}$ $-\dfrac{1}{x^{4}} \to -\infty$$\text{.}$ $\text{Hence}$ $\lim_{x \to 0} \left(-\dfrac{1}{x^{4}}\right)$ $=$ $-\infty$$\text{.}$', 'Infinite Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{The}$ $\text{function}$ $f(x)$ $=$ $(x^2 - 4)/(x - 2) is undefined at x$ $=$ $2$$\text{.}$ $\text{Classify}$ $\text{the}$ $\text{discontinuity}$ $\text{at}$ $\text{x}$ $\text{=}$ $\text{2.}$', '["$\\text{removable}$ $\\text{discontinuity}$", "$\\text{jump}$ $\\text{discontinuity}$", "$\\text{essential}$ $\\text{(infinite)}$ $\\text{discontinuity}$", "$\\text{f}$ $\\text{is}$ $\\text{actually}$ $\\text{continuous}$ $\\text{at}$ $\\text{x=2}$"]'::jsonb, 0, '$f(2)$ $\text{is}$ $\text{undefined}$ $\text{(division}$ $\text{by}$ $\text{zero),}$ $\text{but}$ $\lim_{x \to 2} \dfrac{x^{2}-4}{x-2}$ $=$ $\lim_{x \to 2} \dfrac{(x-2)(x+2)}{x-2}$ $=$ $\lim_{x \to 2}(x+2)$ $=$ $4$$\text{,}$ $\text{which}$ $\text{exists.}$ $\text{Since}$ $\text{the}$ $\text{limit}$ $\text{exists}$ $\text{even}$ $\text{though}$ $f(2)$ $\text{does}$ $\text{not,}$ $\text{the}$ $\text{discontinuity}$ $\text{can}$ $\text{be}$ $\text{removed}$ $\text{by}$ $\text{defining}$ $f(2)=4$ $\text{--}$ $\text{this}$ $\text{is}$ $\text{a}$ $\text{removable}$ $\text{discontinuity.}$', 'Types of Discontinuity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{A}$ $\text{function}$ $\text{f}$ $\text{is}$ $\text{defined}$ $\text{by}$ $f(x) = x+1$ $\text{for}$ $x<1$ $\text{and}$ $f(x) = 4-x$ $\text{for}$ $\text{x}$ $\text{greater}$ $\text{than}$ $\text{or}$ $\text{equal}$ $\text{to}$ $\text{1.}$ $\text{Classify}$ $\text{the}$ $\text{discontinuity}$ $\text{of}$ $\text{f}$ $\text{at}$ $\text{x}$ $\text{=}$ $\text{1.}$', '["$\\text{jump}$ $\\text{discontinuity}$", "$\\text{removable}$ $\\text{discontinuity}$", "$\\text{f}$ $\\text{is}$ $\\text{continuous}$ $\\text{at}$ $\\text{x=1}$", "$\\text{essential}$ $\\text{discontinuity}$ $\\text{that}$ $\\text{is}$ $\\text{not}$ $\\text{a}$ $\\text{jump}$"]'::jsonb, 0, '$\lim_{x \to 1^-} f(x)$ $=$ $\lim_{x \to 1^-}(x+1)$ $=$ $2$ $\text{and}$ $\lim_{x \to 1^+} f(x)$ $=$ $\lim_{x \to 1^+}(4-x)$ $=$ $3$$\text{.}$ $\text{Both}$ $\text{one-sided}$ $\text{limits}$ $\text{exist}$ $\text{but}$ $\text{are}$ $\text{unequal}$ $\text{(}$$2 \neq 3$$\text{),}$ $\text{so}$ $\lim_{x \to 1} f(x)$ $\text{does}$ $\text{not}$ $\text{exist.}$ $\text{Since}$ $\text{both}$ $\text{one-sided}$ $\text{limits}$ $\text{exist}$ $\text{but}$ $\text{differ,}$ $\text{this}$ $\text{is}$ $\text{a}$ $\text{jump}$ $\text{discontinuity.}$', 'Types of Discontinuity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Classify}$ $\text{the}$ $\text{discontinuity}$ $\text{of}$ $f(x) = 1/x at x = 0$$\text{.}$', '["$\\text{essential}$ $\\text{(infinite)}$ $\\text{discontinuity}$", "$\\text{removable}$ $\\text{discontinuity}$", "$\\text{jump}$ $\\text{discontinuity}$", "$\\text{f}$ $\\text{is}$ $\\text{continuous}$ $\\text{at}$ $\\text{x=0}$"]'::jsonb, 0, '$\text{As}$ $x \to 0^{+}$$\text{,}$ $\dfrac{1}{x} \to \infty$$\text{,}$ $\text{and}$ $\text{as}$ $x \to 0^{-}$$\text{,}$ $\dfrac{1}{x} \to -\infty$$\text{.}$ $\text{Neither}$ $\text{one-sided}$ $\text{limit}$ $\text{exists}$ $\text{as}$ $\text{a}$ $\text{finite}$ $\text{number,}$ $\text{so}$ $\text{this}$ $\text{cannot}$ $\text{be}$ $\text{patched}$ $\text{by}$ $\text{redefining}$ $\text{a}$ $\text{single}$ $\text{point}$ $\text{--}$ $\text{it}$ $\text{is}$ $\text{an}$ $\text{essential}$ $\text{(infinite)}$ $\text{discontinuity.}$', 'Types of Discontinuity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Let}$ $f(x) = (x^2 - 9)/(x - 3)$ $\text{for}$ $\text{x}$ $\text{not}$ $\text{equal}$ $\text{to}$ $\text{3,}$ $\text{and}$ $f(3)$ $= 10$$\text{.}$ $\text{Classify}$ $\text{the}$ $\text{discontinuity}$ $\text{of}$ $\text{f}$ $\text{at}$ $\text{x}$ $\text{=}$ $\text{3.}$', '["$\\text{removable}$ $\\text{discontinuity}$", "$\\text{jump}$ $\\text{discontinuity}$", "$\\text{f}$ $\\text{is}$ $\\text{continuous}$ $\\text{at}$ $\\text{x=3}$", "$\\text{essential}$ $\\text{discontinuity}$"]'::jsonb, 0, '$\lim_{x \to 3} \dfrac{x^{2}-9}{x-3}$ $=$ $\lim_{x \to 3}(x+3)$ $=$ $6$$\text{,}$ $\text{which}$ $\text{exists,}$ $\text{but}$ $\text{the}$ $\text{given}$ $\text{value}$ $f(3) = 10 \neq 6$$\text{.}$ $\text{Since}$ $\text{the}$ $\text{limit}$ $\text{exists}$ $\text{but}$ $\text{does}$ $\text{not}$ $\text{match}$ $\text{the}$ $\text{defined}$ $\text{function}$ $\text{value,}$ $\text{this}$ $\text{is}$ $\text{a}$ $\text{removable}$ $\text{discontinuity}$ $\text{(redefining}$ $f(3)=6$ $\text{would}$ $\text{make}$ $f$ $\text{continuous}$ $\text{there).}$', 'Types of Discontinuity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{The}$ $\text{greatest}$ $\text{integer}$ $\text{function}$ $f(x)$ $=$ $[x] (the largest integer <= x) is discontinuous at every integer$$\text{.}$ $\text{Classify}$ $\text{the}$ $\text{discontinuity}$ $\text{at}$ $\text{x}$ $\text{=}$ $\text{2.}$', '["$\\text{jump}$ $\\text{discontinuity}$", "$\\text{removable}$ $\\text{discontinuity}$", "$\\text{essential}$ $\\text{discontinuity}$ $\\text{that}$ $\\text{is}$ $\\text{not}$ $\\text{a}$ $\\text{jump}$", "$\\text{f}$ $\\text{is}$ $\\text{continuous}$ $\\text{at}$ $\\text{x=2}$"]'::jsonb, 0, '$\lim_{x \to 2^-} [x] = 1$ $\text{(just}$ $\text{below}$ $\text{2,}$ $\text{the}$ $\text{greatest}$ $\text{integer}$ $\text{is}$ $\text{still}$ $\text{1)}$ $\text{while}$ $\lim_{x \to 2^+} [x] = 2$$\text{.}$ $\text{Both}$ $\text{one-sided}$ $\text{limits}$ $\text{exist}$ $\text{but}$ $\text{are}$ $\text{unequal,}$ $\text{so}$ $\text{this}$ $\text{is}$ $\text{a}$ $\text{jump}$ $\text{discontinuity.}$', 'Types of Discontinuity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{inverse}$ $\text{of}$ $\text{the}$ $\text{function}$ $f(x) = 2x + 3$$\text{.}$', '["$f^{-1}(x) = (x-3)/2$", "$f^{-1}(x) = 2x-3$", "$f^{-1}(x) = (x+3)/2$", "$f^{-1}(x) = x/2 - 3$"]'::jsonb, 0, '$\text{Set}$ $y = 2x+3$ $\text{and}$ $\text{solve}$ $\text{for}$ $x$$\text{:}$ $y - 3 = 2x$$\text{,}$ $\text{so}$ $x = \dfrac{y-3}{2}$$\text{.}$ $\text{Swapping}$ $\text{the}$ $\text{roles}$ $\text{of}$ $x$ $\text{and}$ $y$ $\text{gives}$ $f^{-1}(x) = \dfrac{x-3}{2}$$\text{.}$', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{inverse}$ $\text{of}$ $\text{the}$ $\text{function}$ $f(x) = x^3$$\text{.}$', '["$f^{-1}(x) = x^{1/3}$", "$f^{-1}(x) = x^3$", "$f^{-1}(x) = 1/x^3$", "$f^{-1}(x) = 3x$"]'::jsonb, 0, '$\text{Set}$ $y = x^{3}$ $\text{and}$ $\text{solve}$ $\text{for}$ $x$$\text{:}$ $\text{taking}$ $\text{the}$ $\text{cube}$ $\text{root}$ $\text{of}$ $\text{both}$ $\text{sides,}$ $x = y^{1/3}$$\text{.}$ $\text{Swapping}$ $x$ $\text{and}$ $y$ $\text{gives}$ $f^{-1}(x) = x^{1/3}$$\text{.}$', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{If}$ $f(x) = 5x - 2$$\text{,}$ $\text{find}$ $f^{-1}(8)$$\text{.}$', '["$2$", "$3$", "$38$", "$1$"]'::jsonb, 0, '$\text{Set}$ $y = 5x-2$ $\text{and}$ $\text{solve}$ $\text{for}$ $x$$\text{:}$ $x = \dfrac{y+2}{5}$$\text{,}$ $\text{so}$ $f^{-1}(x) = \dfrac{x+2}{5}$$\text{.}$ $\text{Then}$ $f^{-1}(8)$ $=$ $\dfrac{8+2}{5}$ $=$ $\dfrac{10}{5}$ $=$ $2$$\text{.}$ $\text{(Check:}$ $f(2) = 5(2)-2 = 8$$\text{,}$ $\text{confirming}$ $\text{the}$ $\text{inverse.)}$', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{The}$ $\text{function}$ $f(x) = x^2$ $\text{for}$ $\text{x}$ $\text{>=}$ $\text{0}$ $\text{has}$ $\text{inverse}$ $f^{-1}(x) = \sqrt{x}$$\text{.}$ $\text{Find}$ $f^{-1}(9)$$\text{.}$', '["$3$", "$9$", "$81$", "$4.5$"]'::jsonb, 0, '$\text{Since}$ $f^{-1}(x) = \sqrt{x}$ $\text{for}$ $x \geq 0$$\text{,}$ $f^{-1}(9) = \sqrt{9} = 3$$\text{.}$ $\text{(Check:}$ $f(3) = 3^{2} = 9$$\text{,}$ $\text{confirming}$ $\text{the}$ $\text{inverse.)}$', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{inverse}$ $\text{of}$ $\text{the}$ $\text{function}$ $f(x) = (x + 1)/2$$\text{.}$', '["$f^{-1}(x) = 2x - 1$", "$f^{-1}(x) = 2x + 1$", "$f^{-1}(x) = (x-1)/2$", "$f^{-1}(x) = x/2 - 1$"]'::jsonb, 0, '$\text{Set}$ $y = \dfrac{x+1}{2}$ $\text{and}$ $\text{solve}$ $\text{for}$ $x$$\text{:}$ $2y = x+1$$\text{,}$ $\text{so}$ $x = 2y - 1$$\text{.}$ $\text{Swapping}$ $x$ $\text{and}$ $y$ $\text{gives}$ $f^{-1}(x) = 2x - 1$$\text{.}$', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{shell}$ $\text{method,}$ $\text{find}$ $\text{the}$ $\text{volume}$ $\text{of}$ $\text{the}$ $\text{solid}$ $\text{formed}$ $\text{by}$ $\text{revolving}$ $\text{about}$ $\text{the}$ $\text{y-axis}$ $\text{the}$ $\text{region}$ $\text{under}$ $y = x^2 from x=0 to x=2$$\text{.}$', '["$8\\pi$", "$16\\pi/3$", "$4\\pi$", "$32\\pi/5$"]'::jsonb, 0, '$\text{By}$ $\text{the}$ $\text{shell}$ $\text{method,}$ $\text{revolving}$ $\text{about}$ $\text{the}$ $\text{y-axis}$ $\text{gives}$ $V$ $=$ $2\pi \int_{0}^{2} x \cdot f(x) \, dx$ $=$ $2\pi \int_{0}^{2} x \cdot x^{2} \, dx$ $=$ $2\pi \int_{0}^{2} x^{3} \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{of}$ $\text{the}$ $\text{integrand}$ $\text{is}$ $F(x) = \dfrac{x^{4}}{4}$$\text{,}$ $\text{so}$ $V$ $=$ $2\pi \left[F(2)-F(0)\right]$ $=$ $2\pi \left[\dfrac{16}{4} - 0\right]$ $=$ $2\pi(4)$ $=$ $8\pi$$\text{.}$', 'The Shell Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{shell}$ $\text{method,}$ $\text{find}$ $\text{the}$ $\text{volume}$ $\text{of}$ $\text{the}$ $\text{solid}$ $\text{formed}$ $\text{by}$ $\text{revolving}$ $\text{about}$ $\text{the}$ $\text{y-axis}$ $\text{the}$ $\text{region}$ $\text{under}$ $y = x from x=0 to x=3$$\text{.}$', '["$18\\pi$", "$9\\pi$", "$27\\pi$", "$6\\pi$"]'::jsonb, 0, '$V$ $=$ $2\pi \int_{0}^{3} x \cdot x \, dx$ $=$ $2\pi \int_{0}^{3} x^{2} \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \dfrac{x^{3}}{3}$$\text{,}$ $\text{so}$ $V$ $=$ $2\pi \left[F(3)-F(0)\right]$ $=$ $2\pi \left[9 - 0\right]$ $=$ $18\pi$$\text{.}$', 'The Shell Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{shell}$ $\text{method,}$ $\text{find}$ $\text{the}$ $\text{volume}$ $\text{of}$ $\text{the}$ $\text{solid}$ $\text{formed}$ $\text{by}$ $\text{revolving}$ $\text{about}$ $\text{the}$ $\text{y-axis}$ $\text{the}$ $\text{region}$ $\text{under}$ $y = x^3 from x=0 to x=1$$\text{.}$', '["$2\\pi/5$", "$\\pi/4$", "$\\pi/3$", "$2\\pi/3$"]'::jsonb, 0, '$V$ $=$ $2\pi \int_{0}^{1} x \cdot x^{3} \, dx$ $=$ $2\pi \int_{0}^{1} x^{4} \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \dfrac{x^{5}}{5}$$\text{,}$ $\text{so}$ $V$ $=$ $2\pi \left[F(1)-F(0)\right]$ $=$ $2\pi \left[\dfrac{1}{5} - 0\right]$ $=$ $\dfrac{2\pi}{5}$$\text{.}$', 'The Shell Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{shell}$ $\text{method,}$ $\text{find}$ $\text{the}$ $\text{volume}$ $\text{of}$ $\text{the}$ $\text{solid}$ $\text{formed}$ $\text{by}$ $\text{revolving}$ $\text{about}$ $\text{the}$ $\text{y-axis}$ $\text{the}$ $\text{region}$ $\text{under}$ $y = \sqrt{x} from x=0 to x=4$$\text{.}$', '["$128\\pi/5$", "$16\\pi$", "$64\\pi/3$", "$8\\pi$"]'::jsonb, 0, '$V$ $=$ $2\pi \int_{0}^{4} x \cdot \sqrt{x} \, dx$ $=$ $2\pi \int_{0}^{4} x^{3/2} \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \dfrac{2}{5}x^{5/2}$$\text{,}$ $\text{so}$ $V$ $=$ $2\pi \left[F(4)-F(0)\right]$ $=$ $2\pi \left[\dfrac{2}{5}(32) - 0\right]$ $=$ $2\pi \cdot \dfrac{64}{5}$ $=$ $\dfrac{128\pi}{5}$$\text{.}$', 'The Shell Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{In}$ $\text{the}$ $\text{partial}$ $\text{fraction}$ $\text{decomposition}$ $\text{1/[(x-1)(x+1)]}$ $\text{=}$ $\text{A/(x-1)}$ $\text{+}$ $\text{B/(x+1),}$ $\text{find}$ $\text{A.}$', '["$1/2$", "$-1/2$", "$1$", "$-1$"]'::jsonb, 0, '$\text{Clearing}$ $\text{denominators:}$ $1 = A(x+1) + B(x-1)$$\text{.}$ $\text{Setting}$ $x=1$$\text{:}$ $1$ $=$ $A(2) + B(0) \Rightarrow A$ $=$ $\dfrac{1}{2}$$\text{.}$', 'Method of Partial Fractions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{In}$ $\text{the}$ $\text{partial}$ $\text{fraction}$ $\text{decomposition}$ $\text{1/[(x-1)(x+1)]}$ $\text{=}$ $\text{A/(x-1)}$ $\text{+}$ $\text{B/(x+1),}$ $\text{find}$ $\text{B.}$', '["$-1/2$", "$1/2$", "$1$", "$-1$"]'::jsonb, 0, '$\text{Clearing}$ $\text{denominators:}$ $1 = A(x+1) + B(x-1)$$\text{.}$ $\text{Setting}$ $x=-1$$\text{:}$ $1$ $=$ $A(0) + B(-2) \Rightarrow B$ $=$ $-\dfrac{1}{2}$$\text{.}$', 'Method of Partial Fractions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{In}$ $\text{the}$ $\text{partial}$ $\text{fraction}$ $\text{decomposition}$ $\text{5/[(x-2)(x+3)]}$ $\text{=}$ $\text{A/(x-2)}$ $\text{+}$ $\text{B/(x+3),}$ $\text{find}$ $\text{A}$ $\text{and}$ $\text{B.}$', '["$A = 1, B = -1$", "$A = 5, B = -5$", "$A = -1, B = 1$", "$A = 1, B = 1$"]'::jsonb, 0, '$\text{Clearing}$ $\text{denominators:}$ $5 = A(x+3) + B(x-2)$$\text{.}$ $\text{Setting}$ $x=2$$\text{:}$ $5 = A(5) \Rightarrow A=1$$\text{.}$ $\text{Setting}$ $x=-3$$\text{:}$ $5 = B(-5) \Rightarrow B=-1$$\text{.}$', 'Method of Partial Fractions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{In}$ $\text{the}$ $\text{partial}$ $\text{fraction}$ $\text{decomposition}$ $\text{(3x+1)/[(x-1)(x+2)]}$ $\text{=}$ $\text{A/(x-1)}$ $\text{+}$ $\text{B/(x+2),}$ $\text{find}$ $\text{A.}$', '["$4/3$", "$5/3$", "$3$", "$1$"]'::jsonb, 0, '$\text{Clearing}$ $\text{denominators:}$ $3x+1 = A(x+2) + B(x-1)$$\text{.}$ $\text{Setting}$ $x=1$$\text{:}$ $3(1)+1$ $=$ $A(3) \Rightarrow 4$ $=$ $3A \Rightarrow A$ $=$ $\dfrac{4}{3}$$\text{.}$', 'Method of Partial Fractions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{In}$ $\text{the}$ $\text{partial}$ $\text{fraction}$ $\text{decomposition}$ $\text{1/[x(x-1)\textasciicircum{}2]}$ $\text{=}$ $\text{A/x}$ $\text{+}$ $\text{B/(x-1)}$ $\text{+}$ $\text{C/(x-1)\textasciicircum{}2,}$ $\text{find}$ $\text{C}$ $\text{(the}$ $\text{coefficient}$ $\text{of}$ $\text{the}$ $\text{repeated-factor}$ $\text{term}$ $\text{1/(x-1)\textasciicircum{}2).}$', '["$1$", "$-1$", "$2$", "$0$"]'::jsonb, 0, '$\text{Clearing}$ $\text{denominators:}$ $1 = A(x-1)^{2} + Bx(x-1) + Cx$$\text{.}$ $\text{Setting}$ $x=1$ $\text{eliminates}$ $\text{the}$ $A$ $\text{and}$ $B$ $\text{terms:}$ $1 = A(0) + B(0) + C(1) \Rightarrow C = 1$$\text{.}$', 'Method of Partial Fractions', false);
